NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'Joshua'

CHAPTERS = {
    1: {
        1: 'Und nach dem Tode Mosis, des Dieners des Herrn, sprach der Herr zu Josue, Nuns Sohn und Mosis Diener, also:',
        2: '"Mein Diener Moses ist tot. Auf! Ziehe hier über den Jordan, du und dieses ganze Volk, in das Land, das ich den Söhnen Israels gebe!',
        3: 'Wie ich Moses versprochen, gebe ich euch jeden Platz, den euer Fuß betritt.',
        4: 'Hier von der Wüste und dem Libanon bis zum großen Strom, dem Euphratstrom, bis zum ganzen Chittiterland und bis zum großen Meer im Westen erstreckt sich euer Reich!',
        5: 'Vor dir hält niemand stand, solange du lebst. Wie ich mit Moses gewesen bin, bin ich mit dir. Ich lasse dich nicht und verlasse dich nicht.',
        6: 'Sei stark und fest! Denn du sollst dieses Volk in das Land führen, das ihnen zu geben ich ihren Vätern zugeschworen habe.',
        7: 'Nur sei stark und fest entschlossen, darauf zu achten, ganz nach der Lehre zu tun, die dir mein Diener Moses geboten! Weiche nicht davon ab, weder nach rechts noch nach links, daß du Glück habest in allem, woran du gehst!',
        8: 'Dies Buch der Lehre soll nie von deinem Munde weichen! Sinne darüber Tag und Nacht, daß du mit Vorbedacht ganz nach dem, was darin geschrieben, handelst! Dann führst du deinen Weg durch und hast Glück.',
        9: 'Habe ich dir nicht geboten: Sei mutig und entschlossen? Zage nicht und zittere nicht! Mit dir ist der Herr, dein Gott, überall, wo du gehst."',
        10: 'Da gebot Josue den Amtleuten des Volkes:',
        11: '"Schreitet durch das Lager und gebietet dem Volke: \'Besorgt euch Zehrung! Denn nach drei Tagen zieht ihr hier über den Jordan, und besetzt das Land, das der Herr, euer Gott, euch zu eigen gibt.\'"',
        12: 'Zu den Rubeniten aber, zu den Gaditen und dem Halbstamme Manasse sprach Josue:',
        13: '"Gedenket dessen, was euch der Diener des Herrn, Moses, geboten mit den Worten: \'Der Herr, euer Gott, hat euch an euer Ziel gebracht und euch dies Land gegeben.\'',
        14: 'Eure Weiber, eure kleinen Kinder und euer Vieh mögen in dem Lande bleiben, das Moses diesseits des Jordan euch gegeben hat. Ihr aber, alle Wehrtüchtigen, sollt geordnet euren Brüdern voranschreiten! So helft ihnen,',
        15: 'bis der Herr eure Brüder an ihr Ziel bringt wie euch und auch sie das Land besetzen, das der Herr, euer Gott, ihnen geben will! Dann kehrt in euer eigenes Land zurück und besetzt es, das euch der Diener des Herrn, Moses, diesseits des Jordan im Osten gegeben hat."',
        16: 'Da antworteten sie Josue: "Alles, was du uns heißest, wollen wir tun, und wohin du uns schickst, gehen wir.',
        17: 'Wie wir auf Moses gehört, so wollen wir auch auf dich hören. Nur möge der Herr, dein Gott, mit dir sein, wie er mit Moses gewesen"',
        18: 'Wer deiner Weisung widerspricht und nicht auf deine Worte hört, was du ihm irgendwie gebietest, der sei des Todes! Sei nur mutig und entschlossen!"',
    },
    2: {
        1: 'Und Josue, Nuns Sohn, sandte von Sittim heimlich zwei Männer aus als Kundschafter und sprach: "Geht! Beseht die Gegend, besonders Jericho!" Sie gingen und kamen zum Hause einer Wirtin namens Rachab. Hier kehrten sie ein.',
        2: 'Da ward dem König von Jericho gemeldet: "Heute nacht sind Männer von den Söhnen Israels hierher gekommen, das Land auszuspähen!"',
        3: 'Da sandte Jerichos König zu Rachab und ließ sagen: "Gib die Männer heraus, die zu dir gekommen und dein Haus betreten haben! Sie sind nur gekommen, die ganze Gegend auszuspähen."',
        4: 'Das Weib aber nahm die beiden Männer und verbarg sie. Dann sprach sie: "Gewiß! Die Männer sind zu mir gekommen. Aber ich habe nicht gewußt, woher sie waren.',
        5: 'Um die Zeit des Torschlusses, beim Dunkelwerden, sind die Männer fortgegangen. Ich weiß nicht, wohin die Männer gegangen sind. Jagt ihnen schnell nach! Dann könnt ihr sie einholen."',
        6: 'Sie hatte sie aber aufs Dach geführt und unter Flachsstengeln versteckt, die sie auf dem Dache ausgebreitet hatte.',
        7: 'Die Männer aber jagten ihnen nach, dem Jordan zu, an die Furten. Das Tor schloß man zu, sobald ihre Verfolger draußen waren.',
        8: 'Sie hatten sich aber noch nicht hingelegt, da kam sie zu ihnen auf das Dach',
        9: 'und sprach zu den Männern: Ich weiß: Der Herr gibt euch das Land. Der Schrecken vor euch hat uns befallen, und alle Insassen des Landes zagen vor euch.',
        10: 'Denn wir haben gehört, wie der Herr das Wasser des Schilfmeeres vor euch ausgetrocknet hat bei eurem Auszug aus Ägypten und was ihr den beiden Amoriterkönigen jenseits des Jordan getan, Sichon und Og, wie ihr sie gebannt habt.',
        11: 'Wir hörten dies; da verzagte unser Herz, und in niemandem hat sich ein Mut wider euch geregt. Denn der Herr, euer Gott, ist droben im Himmel und auf Erden unten Gott.',
        12: 'Und nun schwört mir beim Herrn, daß ihr auch dem Hause meines Vaters Gutes tun wollt, wie ich euch Gutes getan! Gebt mir ein Zeichen der Gewähr dafür,',
        13: 'daß ihr meinen Vater, meine Mutter, meine Brüder und Schwestern und all die Ihrigen leben lasset und unser Leben vom Tode rettet!"',
        14: 'Da sprachen die Männer zu ihr: "Wir bürgen mit unserem eigenen Leben für das eurige, wenn ihr diese unsere Verabredung nicht verratet. Gibt uns der Herr das Land, dann wollen wir dir in Treue Gutes tun."',
        15: 'Sie ließ sie darauf an einem Seil durchs Fenster hinab. Denn ihr Haus war in die Stadtmauer eingebaut, und so wohnte sie an der Stadtmauer.',
        16: 'Sie sprach zu ihnen: "Geht ins Gebirge, daß die Verfolger euch nicht treffen! Verbergt euch dort drei Tage, bis die Verfolger heimgekehrt sind! Dann geht eures Weges!"',
        17: 'Da sprachen die Männer zu ihr: "Wir wollen frei von deinem Eidfluche bleiben, den du uns hast aussprechen lassen.',
        18: 'Kommen wir in das Land, so sollst du die rote Tuchfahne hier an das Fenster knüpfen, durch das du uns heruntergelassen, und Vater, Mutter, Brüder und dein ganzes Vaterhaus zu dir ins Haus nehmen!',
        19: 'Wer dann vor die Tür deines Hauses auf die Straße geht, dessen Blut fällt auf sein Haupt. Wir aber sind schuldfrei. Legt aber jemand Hand an irgendeinen, der bei dir im Hause ist, dann fällt sein Blut auf unser Haupt.',
        20: 'Verrätst du aber unsere Verabredung, so sind wir deines Eidfluches frei, den du uns hast aussprechen lassen."',
        21: 'Sie sprach: "So sei es, wie ihr sagt!" Sie entließ sie, und sie gingen weg. Sie aber band die rote Fahne an das Fenster.',
        22: 'Sie gingen nun weg und kamen ins Gebirge. Dort blieben sie drei Tage, bis die Verfolger zurück waren. Die Verfolger aber hatten den Weg überall abgesucht, aber sie nicht gefunden.',
        23: 'Dann stiegen die beiden Männer wieder vom Gebirge herab, setzten über und kamen zu Josue, Nuns Sohn. Und sie erzählten ihm alles, was ihnen begegnet war.',
        24: 'Sie sprachen zu Josue: "Wahrhaftig! Der Herr gibt uns das ganze Land die Hand; denn alle Insassen des Landes haben Angst vor uns."',
    },
    3: {
        1: 'Und Josue stand frühmorgens auf; da zogen sie von Sittim ab. Sie kamen dann an den Jordan, er und alle Israeliten, und sie nächtigten dort, bevor sie übersetzten.',
        2: 'Nach drei Tagen gingen die Amtsleute durch das Lager',
        3: 'und befahlen dem Volke: "Seht ihr die Bundeslade des Herrn, eures Gottes, von den levitischen Priestern getragen, dann sollt ihr von eurem Standorte abziehen! Und folgt ihr nach -',
        4: 'nur sei zwischen euch und ihr ein Raum von etwa zweitausend Ellen! Kommt aber nicht näher -an sie -, damit ihr den Weg wisset, den ihr gehen sollt! Denn ihr seid ihn bisher noch nie gegangen."',
        5: 'Da sprach Josue zu dem Volke: "Haltet euch rein! Denn morgen wirkt der Herr euch Wunder."',
        6: 'Zu den Priestern aber sprach Josue: "Nehmt die Bundeslade und schreitet dem Volke voran!" Da nahmen sie die Bundeslade und zogen dem Volke voran.',
        7: 'Da sprach der Herr zu Josue: "Heute beginne ich, dich in den Augen von ganz Israel zu verherrlichen, damit sie daran erkennen, daß ich mit dir bin, wie ich mit Moses gewesen.',
        8: 'Du sollst nun den Priestern, den Trägern der Bundeslade, befehlen: \'Kommt ihr zum Rande des Jordanwassers, dann sollt ihr am Jordan stehenbleiben!\'"',
        9: 'Und Josue sprach zu den Israeliten: "Tretet her und höret das Vorhaben des Herrn, eures Gottes!"',
        10: 'Und Josue sprach: "Daran sollt ihr erkennen, daß in eurer Mitte ein lebendiger Gott ist und daß er vor euch vertreibt die Kanaaniter, Chittiter, Chiwiter, Periziter, Girgasiter, Amoriter und Jebusiter:',
        11: 'Die Bundeslade des Herrn der ganzen Erde zieht vor euch durch den Jordan.',
        12: 'Wählt euch inzwischen zwölf Männer aus Israels Stämmen, je einen Mann aus einem Stamm!',
        13: 'Sobald die Füße der Priester, der Träger der Lade des Herrn, des Herrn der ganzen Erde, in das Jordanwasser tauchen, wird das Wasser des Jordan verschwinden; das Wasser aber, das von oben fließt, wird dastehen wie ein Wall."',
        14: 'Das Volk zog nun aus seinen Zelten, den Jordan zu überschreiten. Vor dem Volke die Priester, die Träger der Bundeslade.',
        15: 'Wie die Träger der Lade an den Jordan kamen und die Füße der Priester, der Träger der Lade, kaum ins Wasser tauchten - der Jordan aber war voll in all seinen Nebenflüssen während der ganzen Erntezeit -,',
        16: 'da stand das Wasser, das von oben floß, hatte es sich doch wie ein Wall erhoben, in großer Weite bei der Stadt Adam seitwärts von Saretan. Das Wasser aber, das zu dem Steppenmeere, dem Salzmeere floß, verschwand völlig. So zog das Volk hinüber auf Jericho zu.',
        17: 'Die Priester, die Träger der Bundeslade des Herrn, standen im Trockenen genau in der Mitte des Jordan, während ganz Israel im Trockenen hinüberzog, bis das ganze Volk den Jordan vollends überschritten hatte.',
    },
    4: {
        1: 'Sobald das ganze Volk den Jordan vollends überschritten hatte, sprach der Herr zu Josue:',
        2: '"Wählt euch aus dem Volke zwölf Männer, je einen Mann aus einem Stamme,',
        3: 'und weiset sie also an: \'Nehmt euch zwölf Steine von hier, gerade aus des Jordans Mitte, von diesem Platz, auf dem der Priester Füße stehen, schafft sie mit euch hinüber und legt sie an den Ort, wo ihr heute nächtigen wollt!\'"',
        4: 'Da berief Josue die zwölf Männer, die er aus den Israeliten bestellt hatte, je einen Mann aus einem Stamm.',
        5: 'Und Josue sprach zu ihnen: "Geht vor die Lade des Herrn, eures Gottes, mitten in den Jordan und ladet euch jeder einen Stein auf seine Schulter nach der Zahl der Stämme Israels.',
        6: "Dies sei ein Merkzeichen unter euch! Fragen später eure Kinder: 'Was bedeuten euch diese Steine?'",
        7: 'dann sagt ihnen: \'Sie bedeuten, daß das Jordanwasser vor der Bundeslade des Herrn verschwunden ist, als sie in den Jordan kam. Das Wasser des Jordan ist verschwunden, und diese Steine dienen den Israeliten zum ewigen Gedenken.\'"',
        8: 'Die Israeliten taten so, wie Josue befahl. Sie nahmen zwölf Steine mitten aus dem Jordan, wie der Herr zu Josue gesagt, nach der Zahl der israelitischen Stämme, schafften sie mit sich in das Nachtlager hinüber und legten sie dort nieder.',
        9: 'Zwölf andere Steine hatte Josue mitten im Jordan niederlegen lassen an der Stelle, wo die Füße der Priester stehen sollten, der Träger der Bundeslade. Sie blieben dort bis auf diesen Tag.',
        10: 'Die Priester aber, die Träger der Lade, standen mitten im Jordan, bis alles ausgeführt war, was der Herr den Josue geheißen hatte, dem Volke zu sagen, gemäß dem Befehle Mosis an Josue. Das Volk aber zog rasch hinüber.',
        11: 'Erst als das ganze Volk vollends hinüber war, zog auch die Lade des Herrn hinüber, und die Priester stellten sich an die Spitze des Volkes.',
        12: 'Die Rubeniten, die Gaditen und der Halbstamm Manasse zogen geordnet vor den Israeliten hinüber, wie ihnen Moses befohlen hatte.',
        13: 'An 40.000 kriegsbereite Männer zogen vor dem Herrn nach Jerichos Steppe in den Kampf.',
        14: 'An jenem Tage hatte der Herr den Josue verherrlicht in ganz Israels Augen, und sie fürchteten ihn sein Leben lang, wie sie Moses gefürchtet hatten.',
        15: 'Der Herr aber sprach zu Josue:',
        16: '"Befiehl den Priestern, den Trägern der Lade des Zeugnisses, sie sollen aus dem Jordan steigen."',
        17: 'Da befahl Josue den Priestern: "Steigt aus dem Jordan!"',
        18: 'So stiegen die Priester, die Träger der Bundeslade des Herrn, aus dem Jordanbett. Kaum aber berührten der Priester Fußsohlen das Trockene, so nahm das Wasser des Jordan wieder den natürlichen Lauf und trat wie vorher über all seine Ufer.',
        19: 'Das Volk aber stieg am zehnten Tage des ersten Monats aus dem Jordan und lagerte im Gilgal an Jerichos Ostgrenze.',
        20: 'Jene zwölf Steine aber, die sie aus dem Jordan genommen, stellte Josue im Gilgal auf.',
        21: 'Er sprach zu den Israeliten: "Fragen später eure Kinder ihre Väter: \'Was bedeuten diese Steine?\',',
        22: "so Iehret eure Kinder: 'Israel ist hier trockenen Fußes über den Jordan gezogen',",
        23: 'weil der Herr, euer Gott, das Jordanwasser vor euch hatte vertrocknen lassen, bis ihr hinüber waret, wie der Herr, euer Gott, mit dem Schilfmeer getan, das er vor uns vertrocknen ließ, bis wir hinüber waren,',
        24: 'damit alle Völker der Erde einsehen, daß des Herrn Hand stark ist, und daß sie so den Herrn, euren Gott, allzeit fürchten."',
    },
    5: {
        1: 'Sobald die Amoriterkönige alle jenseits des Jordan im Westen und alle Kanaaniter am Meere hörten, wie der Herr das Wasser des Jordan vor den Israeliten hatte vertrocknen lassen, bis sie hinüber waren, verzagte ihr Herz, und sie hatten keinen Mut mehr gegen die Israeliten.',
        2: 'In jener Zeit gebot der Herr dem Josue: "Mach dir Steinmesser! Beschneide zum zweitenmal die Söhne Israels!"',
        3: 'Da machte sich Josue Steinmesser und beschnitt die Israeliten wieder an der Spitze der Glieder.',
        4: 'Dies war der Grund, weshalb Josue beschnitten hatte: Das ganze Volk, das aus Ägypten zog, die Männer, alle Kriegsleute, waren unterwegs in der Wüste gestorben nach ihrem Auszuge aus Ägypten.',
        5: 'Denn das ganze Volk, das aus Ägypten auszog, war beschnitten gewesen. Dagegen hatte man niemand von dem Volke beschnitten, das nach dem Auszug aus Ägypten unterwegs in der Wüste geboren ward.',
        6: 'Denn vierzig Jahre zogen die Israeliten in der Wüste umher, bis das ganze Geschlecht weggestorben war, die Kriegsleute, die aus Ägypten gezogen, aber des Herrn Weisung nicht gehorcht hatten und denen der Herr geschworen, daß er sie das Land nicht sehen lasse, das uns zu geben der Herr ihren Vätern zugeschworen, ein Land von Milch und Honig fließend.',
        7: 'Ihre Söhne aber hatte er an ihrer Statt aufkommen lassen, und sie hatte Josue beschnitten. Denn sie waren unbeschnitten gewesen, weil man sie unterwegs nicht beschnitten hatte.',
        8: 'Als alles Volk zu Ende beschnitten war, blieben sie an ihrer Stelle im Lager bis zu ihrer Genesung.',
        9: 'Und der Herr sprach zu Josue: "Heute habe ich Ägyptens Schande von euch gewälzt." Daher heißt der Ort Gilgal bis auf diesen Tag.',
        10: 'Die Israeliten lagerten im Gilgal, und sie hielten am vierzehnten Tage des Monats am Abend in Jerichos Steppe das Passah.',
        11: 'Sie aßen am nächsten Tage nach dem Passah von den Früchten des Bodens, ungesäuerte Brote und geröstetes Korn noch am selben Tage.',
        12: 'Am nächsten Tage aber blieb das Manna aus, als sie von den Früchten des Bodens aßen. Für die Israeliten gab es kein Manna mehr. So aßen sie in jenem Jahr von dem Ertrag des Landes Kanaan.',
        13: 'Als aber Josue bei Jericho war, schaute er auf. Da sah er sich gegenüber einem Mann mit gezücktem Schwert in der Hand. Josue ging auf ihn zu und sprach zu ihm: "Bist du für uns oder für unsere Feinde?"',
        14: 'Er sprach: "Nein! Ich bin der Führer der Kriegsschar des Herrn. Eigens bin ich gekommen." Da fiel Josue auf sein Antlitz zur Erde, huldigte und fragte ihn. "Was hat mein Herr seinem Sklaven zu sagen?"',
        15: 'Da sprach der Anführer der Kriegsschar des Herrn zu Josue: "Zieh deine Schuhe aus! Denn heilig ist der Ort, worauf du stehst." Und Josue tat so.',
    },
    6: {
        1: 'Jericho aber war eine Sperrfestung. Nun wurde es von den Israeliten eingeschlossen. Und niemand konnte aus noch ein.',
        2: 'Da sprach der Herr zu Josue: "Jetzt gebe ich Jericho in deine Hand nebst seinem König und den Kriegern.',
        3: 'Zieht um die Stadt, ihr Streiter all! Zieht einmal um die Stadt! So sollst du sechs Tage tun.',
        4: 'Und sieben Priester sollen sieben Lärmhörner vor der Lade tragen! Am siebten Tage sollt ihr siebenmal um die Stadt ziehen, und die Priester sollen in die Hörner stoßen!',
        5: 'Wenn das Lärmhorn anhaltend ertönt und wenn ihr den Hörnerschall hört, dann soll das ganze Volk ein gewaltiges Geschrei erheben! Dann stürzt die Stadtmauer in sich zusammen, und das Volk kann einziehen, jeder, wo er steht."',
        6: 'Josue, Nuns Sohn, berief nun die Priester und sprach zu ihnen: "Tragt die Bundeslade! Sieben Priester sollen sieben Lärmhörner vor des Herrn Lade tragen!"',
        7: 'Und sie sprachen zum Volke: "Zieht rings um die Stadt! Die Vorhut soll vor des Herrn Lade herziehen!"',
        8: 'Es geschah, wie Josue zum Volke gesagt hatte. Die sieben Priester, die die sieben Lärmhörner vor dem Herrn trugen, zogen einher und stießen in die Hörner, und die Bundeslade des Herrn kam hinter ihnen.',
        9: 'Die Vorhut aber ging vor den in die Hörner stoßenden Priestern, und die Nachhut ging hinter der Lade, fort und fort in die Hörner stoßend.',
        10: 'Dem Volke aber gebot Josue: "Ihr sollt nicht lärmen und eure Stimme nicht hören lassen! Kein Laut soll aus eurem Mund kommen, bis ich euch sage: \'Schreit!\' Dann erhebt das Kriegsgeschrei!"',
        11: 'So ließ er die Lade des Herrn einmal rings um die Stadt gehen. Dann gingen sie ins Lager und nächtigten im Lager.',
        12: 'Josue aber stand früh am Morgen auf; da nahmen die Priester die Lade des Herrn.',
        13: 'Die sieben Priester, die Träger der sieben Lärmhörner vor des Herrn Lade, zogen hin und stießen fort und fort in die Hörner. Die Vorhut ging vor ihnen her, und die Nachhut folgte der Lade des Herrn, fort und fort in die Hörner stoßend.',
        14: 'Sie zogen auch am zweiten Tage einmal um die Stadt und kehrten dann ins Lager zurück. So taten sie sechs Tage.',
        15: 'Am siebten Tage aber erhoben sie sich bei Anbruch der Morgenröte und zogen nach dieser Ordnung siebenmal um die Stadt. Nur an diesem Tage umzogen sie siebenmal die Stadt.',
        16: 'Beim siebtenmal stießen die Priester in die Hörner, und Josue rief dem Volke zu: "Macht ein Geschrei! Denn der Herr gibt die Stadt in eure Hand.',
        17: 'Die Stadt aber und alles, was darin ist, sei dem Herrn gebannt! Nur die Wirtin Rachab soll am Leben bleiben nebst allen, die bei ihr im Hause sind! Denn sie hat die Boten versteckt, die wir gesandt.',
        18: 'Hütet euch aber vor dem Banngut, daß ihr es nicht verschiebt und von dem Banngut nehmt! Ihr brächtet damit das Lager Israels in den Bann und stürztet es ins Unglück.',
        19: 'Alles Silber und Gold, alles eherne und eiserne Gerät sei dem Herrn geweiht! In den Schatz des Herrn soll es kommen!"',
        20: 'Da erhob das Volk ein Geschrei, und sie stießen in die Hörner. Als das Volk nämlich den Hörnerschall vernahm, erhob das Volk ein gewaltiges Geschrei. Da stürzte die Mauer in sich zusammen. Und das Volk zog in die Stadt, wo jeder gerade stand. So nahmen sie die Stadt ein.',
        21: 'Und sie bannten alles in der Stadt, Mann und Weib, jung und alt, Rinder, Schafe und Esel mit des Schwertes Schärfe.',
        22: 'Den beiden Männern aber, die die Gegend erforscht hatten, hatte Josue gesagt: "Geht in das Haus jener Wirtin und holt das Weib mit all den Seinigen von da heraus, wie ihr ihr geschworen habt!"',
        23: 'Da gingen die jungen Männer, die Kundschafter, hin und führten Rachab, ihren Vater, ihre Mutter, ihre Brüder und all die Ihrigen heraus. Ihre ganze Sippe führten sie heraus; dann brachten sie diese außerhalb des Lagers Israels.',
        24: 'Die Stadt aber und alles, was darin, steckten sie in Brand. Nur das Silber und Gold, die ehernen und eisernen Geräte gaben sie in den Schatz des Herrn.',
        25: 'Die Wirtin Rachab aber, ihr Vaterhaus und all die Ihrigen hatte Josue leben lassen. Und so blieb sie unter den Israeliten bis auf diesen Tag, weil sie die Boten versteckt hatte, die Josue gesandt, Jericho auszuspähen.',
        26: 'Zu jener Zeit aber sprach Josue den Fluch aus: "Verflucht sei vor dem Herrn der Mann, der es wagt, diese Stadt Jericho wiederaufzubauen! Auf seinen Erstgeborenen soll er sie gründen und auf seinen Jüngsten ihre Pforten setzen!"',
        27: 'Und der Herr war mit Josue, und sein Ruf ging durch das ganze Land.',
    },
    7: {
        1: 'Die Israeliten aber vergriffen sich am Banngut. Achan nämlich, Karmis Sohn und Zabdis Enkel und Urenkel Zerachs, vom Stamme Juda, nahm vom Banngut. Da entbrannte des Herrn Zorn über die Söhne Israels.',
        2: 'Nun sandte Josue Männer von Jericho nach Ai bei Bet Awen östlich von Betel. Er befahl ihnen: "Geht hinauf und erkundet die Gegend!" Und die Männer gingen hinauf und erkundeten Ai.',
        3: 'Dann kehrten sie zu Josue zurück und berichteten ihm: "Nicht das ganze Volk braucht hinaufzuziehen. Zwei- oder dreitausend Mann mögen hinziehen, Ai zu erobern. Bemühe nicht das ganze Volk dorthin! Denn ihrer sind wenige."',
        4: 'Da zogen vom Volke an dreitausend Mann dorthin. Aber sie flohen vor Ais Leuten.',
        5: 'Die Leute von Ai erschlugen an sechsunddreißig Mann, verfolgten sie vor dem Tore bis zu den Steinbrüchen und schlugen sie am Abhang. Da zerfloß das Herz des Volkes und ward zu Wasser.',
        6: 'Josue aber zerriß seine Kleider und warf sich auf sein Antlitz zu Boden vor des Herrn Lade bis zum Abend, er und Israels Älteste, und sie streuten Staub auf ihr Haupt.',
        7: 'Und Josue sprach: "Ach Herr, Herr! Warum hast Du dies Volk aber den Jordan geführt, wenn Du uns den Amoritem zur Vernichtung preisgeben willst? Wären wir lieber jenseits des Jordan geblieben!',
        8: 'Bitte, Herr! Was soll ich sagen, nachdem Israel seinen Feinden den Rücken gezeigt?',
        9: 'Hören dies die Kanaaniter und alle anderen Insassen des Landes, so kreisen sie uns ein und tilgen unseren Namen aus der Welt. Was willst Du für Deinen großen Namen tun?"',
        10: 'Da sprach der Herr zu Josue: "Steh auf! Wozu liegst du auf deinem Angesicht?',
        11: 'Gesündigt hat Israel, ja, meinen Bund übertreten, den ich ihnen auferlegt habe. Ja, genommen haben sie vom Banngut, ja, gestohlen, ja, verhehlt, ja, unter ihre Geräte getan!',
        12: 'So können die Söhne Israels vor ihren Feinden nicht mehr standhalten. Den Rücken werden sie den Feinden zeigen, sind sie doch dem Banne verfallen. Ich werde künftig nicht mit euch sein, wenn ihr nicht den Bann aus eurer Mitte tilget.',
        13: "Auf! Bereite das Volk zur Reinigung! Verkünde: 'Sorgt dafür, daß ihr morgen rein seid! Denn also spricht der Herr, Gott Israels: Etwas Gebanntes ist bei dir, Israel! Du kannst vor deinen Feinden nicht mehr standhalten, bis ihr das Banngut aus eurer Mitte tilgt.",
        14: 'Tretet morgen stammweise an! Der Stamm, den der Herr herausgreift, soll sippenweise antreten, und die Sippe, die der Herr herausgreift, familienweise! Von der Familie, die der Herr herausgreift, sollen die Männer einzeln antreten.',
        15: 'Wer aber mit dem Gebannten getroffen wird, den soll man mit all seiner Habe verbrennen! Er hat ja den Bund des Herrn übertreten und Schändliches in Israel getan.\'"',
        16: 'Und Josue ließ am anderen Morgen früh Israel stammweise herantreten. Da wurde der Stamm Juda herausgegriffen.',
        17: 'Darauf ließ er Judas Sippen antreten. Da wurde die Sippe der Zerachiter getroffen. Dann ließ er die Sippe der Zerachiter Mann für Mann antreten. Da ward Zabdi getroffen.',
        18: 'Hierauf ließ er seine Familie Mann für Mann antreten. Da ward Achan, Karmis Sohn, Enkel Zabdis und Urenkel Zerachs, aus dem Stamme Juda getroffen.',
        19: 'Da sprach Josue zu Achan: "Mein Sohn! Gib dem Herrn, dem Gott Israels, Ehre und gib ihm Lob! Sage mir, was du getan! Verhehle mir nichts."',
        20: 'Da erwiderte Achan dem Josue und sprach: "Wahrhaftig! Ich habe gegen den Herrn, den Gott Israels, gesündigt. Das und das habe ich getan.',
        21: 'Ich sah unter der Beute einen schönen Mantel aus Sinear, zweihundert Ring Silber und eine Goldzunge, fünfzig Ringe schwer. Mich gelüstete danach, und ich nahm sie. Sie liegen in meinem Zelt im Boden vergraben, das Silber darunter."',
        22: 'Da sandte Josue Boten, und sie liefen in das Zelt. Wirklich war es in seinem Zelt vergraben, das Silber darunter.',
        23: 'Sie nahmen die Sachen aus dem Zelt, brachten sie zu Josue und allen Israeliten und legten sie vor dem Herrn hin.',
        24: 'Da nahm Josue Achan, Zerachs Sohn, das Geld, den Mantel und die Goldzunge, seine Söhne, seine Töchter, seine Rinder, Esel und Schafe, sein Zelt und all das Seine, und ganz Israel zog mit ihm, und sie brachten sie in das Tal Achor.',
        25: 'Dort sprach Josue: "Warum hast du uns ins Unglück gebracht? Dafür bringe dich der Herr jetzt ins Unglück." Da steinigte ihn ganz Israel. Und sie verbrannten ihn und bewarfen ihn mit Steinen.',
        26: 'Dann errichteten sie über ihm einen großen Steinhaufen, der noch heute da ist. Und der Herr ließ von seinem heftigen Zorne. Daher heißt jene Stätte Achortal bis auf diesen Tag.',
    },
    8: {
        1: 'Da sprach der Herr zu Josue: "Sei ohne Furcht und zage nicht! Nimm alles Kriegsvolk mit dir! Auf! Zieh gegen Ai hinauf! Siehe! Ich gebe Ais König, sein Volk, seine Stadt und sein Land in deine Hand.',
        2: 'Tu mit Ai und seinem König, wie du mit Jericho und seinem König getan! Doch dürft ihr seine Beute und sein Vieh euch aneignen. Lege der Stadt einen Hinterhalt auf ihrer Westseite!"',
        3: 'Da erhob sich Josue mit allem Kriegsvolk, gegen Ai zu ziehen. Und Josue wählte nun dreißigtausend Mann aus, tapfere Leute, sandte sie des Nachts ab',
        4: 'und befahl ihnen: "Seht, daß ihr euch gegen die Stadt in einen Hinterhalt legt, westlich der Stadt! Nicht zu weit von der Stadt! Seid alle bereit!',
        5: 'Ich und alles Volk bei mir rücken gegen die Stadt. Kommen sie heraus, uns entgegen, wie zuvor, so fliehen wir vor ihnen.',
        6: "Ziehen sie uns nach, dann locken wir sie von der Stadt fort, weil sie denken: 'Sie fliehen vor uns, wie zuvor.' Während wir vor ihnen fliehen,",
        7: 'sollt ihr euch aus dem Hinterhalte erheben! Dann besetzt die Stadt! Der Herr, euer Gott, gibt sie in eure Hand!',
        8: 'Habt ihr die Stadt genommen, dann sollt ihr Feuer an die Stadt legen! So sollt ihr nach des Herrn Wort tun! Seht! Das befehle ich euch!"',
        9: 'Und Josue schickte sie ab, und sie legten sich in den Hinterhalt zwischen Betel und Ai, westlich von Ai. Josue aber nächtigte damals unter dem Volke.',
        10: 'Am anderen Morgen früh musterte Josue das Volk. Dann zog er mit den Ältesten Israels vor dem Volke nach Ai hinauf.',
        11: 'Und alles Kriegsvolk bei ihm zog hinauf. So kamen sie nahe bis vor die Stadt und lagerten nördlich von Ai, das Tal zwischen ihnen und Ai.',
        12: 'Dann nahm er an fünftausend Mann und legte sie in den Hinterhalt zwischen Betel und Ai, westlich der Stadt.',
        13: 'Und sie stellten das Volk, das ganze Heer, in eine Höhle nördlich der Stadt und seine Nachhut westlich davon. In jener Nacht nächtigte Josue mitten in dem Talgrund.',
        14: 'Als dies der König von Ai sah, eilten die Leute der Stadt in der Frühe wider Israel zum Kampfe, er und sein ganzes Volk zeitig gegen die Steppe zu. Er aber wußte nicht, daß ihm westlich der Stadt ein Hinterhalt drohte.',
        15: 'Josue und ganz Israel ließen sich nun von ihnen schlagen und flohen der Wüste zu.',
        16: 'Da ward alles Volk in der Stadt aufgeboten, sie zu verfolgen. Und sie verfolgten Josue und ließen sich von der Stadt fortlocken.',
        17: 'Zu Ai und Betel war kein Mann mehr übriggeblieben, der nicht hinter Israel hergezogen wäre. Die Stadt aber ließen sie offen und verfolgten Israel.',
        18: 'Da sprach der Herr zu Josue: "Recke den Speer in deiner Hand gegen Ai! Ich gebe es in deine Hand." Da reckte Josue den Speer in seiner Hand gegen die Stadt.',
        19: 'Der Hinterhalt aber hatte sich eilends von seinem Platz erhoben, sobald er die Hand ausstreckte; dann drang er in die Stadt ein, besetzte sie und zündete eilends die Stadt an.',
        20: 'Die Leute von Ai aber wandten sich um. Da sahen sie, wie der Rauch der Stadt zum Himmel stieg. Da hatten sie keinen Raum mehr, hierhin oder dorthin zu fliehen. Denn das zur Wüste geflohene Israel hatte sich gegen den Verfolger gewandt.',
        21: 'Als aber Josue und ganz Israel sahen, daß der Hinterhalt die Stadt erobert hatte und daß der Rauch der Stadt aufstieg, machten sie kehrt und schlugen Ais Leute.',
        22: 'Die anderen aber waren ihnen von der Stadt entgegengezogen. So bekam Israel sie in die Mitte, die einen vor sich, die anderen hinter sich. Und sie schlugen sie, daß von ihnen kein Entronnener und kein Flüchtling mehr übrigblieb.',
        23: 'Den König von Ai aber ergriffen sie lebendig; dann führten sie ihn vor Josue.',
        24: 'Und Israel erschlug alle Insassen Ais im Felde, in der Steppe, wohin sie sie verfolgt hatten. So fielen alle vollzählig durch des Schwertes Schärfe. Dann wandte sich ganz Israel gegen Ai und schlug es mit des Schwertes Schärfe.',
        25: 'Aller, die an jenem Tage fielen, Männer und Weiber, waren es zwölftausend, sämtlich Leute von Ai.',
        26: 'Josue aber hatte seine Hand, ausgereckt mit dem Speere, nicht eingezogen, bis er alle Bewohner Ais gebannt hatte.',
        27: 'Nur das Vieh und die Beute dieser Stadt nahm Israel für sich, nach dem Worte des Herrn, der so dem Josue geboten hatte.',
        28: 'Und Josue verbrannte Ai und machte es zum ewigen Schutthügel, zur Öde bis auf diesen Tag.',
        29: 'Den König von Ai aber hängte er bis zum Abend an den Pfahl. Erst nach Sonnenuntergang ließ Josue seinen Leichnam vom Pfahl nehmen. Dann warf man ihn vor den Eingang des Stadttores und errichtete darüber einen großen Steinhaufen, bis auf den heutigen Tag.',
        30: 'Damals baute Josue dem Herrn, Israels Gott, auf dem Berg Ebal einen Altar,',
        31: 'wie Moses, des Herrn Diener, den Israeliten befohlen und wie es im Buche der Lehre Mosis geschrieben steht, einen Altar aus unbehauenen Steinen, über die man mit keinem Eisen gefahren. Sie brachten darauf dem Herrn Brandopfer dar und schlachteten Mahlopfer.',
        32: 'Auf die Steine schrieb er dort eine Abschrift der Lehre Mosis, der sie den Söhnen Israels vorgeschrieben hatte.',
        33: 'Ganz Israel mit seinen Ältesten, Amtsleuten und Richtern stand zu beiden Seiten der Lade, den levitischen Priestern gegenüber, den Trägern der Bundeslade des Herrn, Fremde und Einheimische, die eine Hälfte gegen den Berg Garizim, die andere gegen den Berg Ebal hin, wie des Herrn Diener, Moses, zur Segnung des Volkes befohlen hatte. Dies war das Erste.',
        34: 'Hernach las er alle Worte der Lehre vor, den Segen und den Fluch, ganz wie im Buche der Lehre geschrieben steht.',
        35: 'Kein Wort von all dem, was Moses geboten, gab es, das Josue nicht der ganzen Gemeinde Israel vorgelesen hätte, auch den Weibern, Kindern und den mit ihnen zugezogenen Fremden.',
    },
    9: {
        1: 'Als davon alle Könige jenseits des Jordan hörten, auf dem Gebirge und in der Niederung, an der ganzen Küste des großen Meeres gegen den Libanon, die Chittiter, Amoriter, Kanaaniter, Periziter, Chiwiter und Jebusiter,',
        2: 'vereinigten sie sich, um einmütig gegen Josue und Israel zu kämpfen.',
        3: 'Auch Gibeons Einwohner hörten, was Josue an Jericho und Ai getan.',
        4: 'Da handelten auch sie, aber listig. Sie gingen und versahen sich mit Reisekost, nahmen aber alte Säcke auf ihre Esel und alte, zermürbte und geflickte Weinschläuche.',
        5: 'Sie zogen auch alte geflickte Schuhe an und alte Kleider, und ihr Brot für die Reise war hart und zerkrümelt.',
        6: 'So gingen sie zu Josue in das Lager im Gilgal und sprachen zu ihm und den Männern Israels: "Wir kommen aus fernem Lande. Schließt mit uns ein Bündnis!"',
        7: 'Da sprachen die israelitischen Männer zu dem Anführer: "Vielleicht wohnst du in unserer Nähe? Wie könnten wir mit dir ein Bündnis schließen?"',
        8: 'Da sprachen sie zu Josue: "Wir sind deine Sklaven." Da fragte sie Josue: "Wer seid ihr und woher kommt ihr?"',
        9: 'Sie sprachen zu ihm: "Deine Sklaven kommen aus fernstem Lande, auf den Ruhm des Herrn, deines Gottes, hin. Denn wir haben gerüchtweise gehört von ihm und von allem, was er in Ägypten getan,',
        10: 'und alles, was er an den beiden Amoriterkönigen jenseits des Jordan getan, an Chesbons König Sichon und an Og, dem Basankönig zu Astarot.',
        11: "Da sagten unsere Ältesten und unseres Landes Insassen alle zu uns: Nehmt Zehrung auf den Weg mit! Geht ihnen entgegen und sprecht zu ihnen: 'Wir sind eure Sklaven!' Und nun schließt mit uns ein Bündnis!",
        12: 'So ist es mit unserem Brote. Noch warm haben wir es zu Hause für die Reise mitgenommen, als wir zu euch ziehen wollten. Nun ist es hart und zerkrümelt.',
        13: 'Die Weinschläuche da sind neu gewesen, als wir sie gefüllt haben. Nun sind sie geborsten. Unsere Kleider und Schuhe da sind durch die weite Reise abgenutzt."',
        14: 'Da beurteilten die Männer sie nach ihrer Zehrung; aber den Mund des Herrn hatten sie nicht befragt.',
        15: 'So machte Josue mit ihnen Freundschaft und schloß mit ihnen ein Bündnis, sie leben zu lassen. Und die Fürsten der Gemeinde schwuren ihnen dies zu.',
        16: 'Drei Tage nach Abschluß des Bündnisses aber hörte man, sie seien aus der Nähe, und zwar ganz nahe bei ihnen.',
        17: 'Da brachen die Israeliten auf und kamen am dritten Tage zu ihren Städten. Ihre Städte waren Gibeon, Kephira, Beerot und Kirjat-Jearim.',
        18: 'Die Israeliten aber schlugen sie nicht, weil ihnen die Fürsten der Gemeinde beim Herrn, Israels Gott, dies zugeschworen hatten. Da murrte die Gemeinde wider die Fürsten.',
        19: 'Da sagten alle Fürsten zur Gesamtgemeinde: "Wir haben ihnen beim Herrn, Israels Gott, geschworen: somit dürfen wir sie nicht antasten.',
        20: 'Das aber wollen wir an ihnen tun: Wir wollen ihnen das Leben schenken, damit nicht ein Zorn über uns komme wegen des Eides, den wir ihnen geschworen."',
        21: 'Und so sprachen die Fürsten von ihnen: "Sie sollen am Leben bleiben; jedoch für die ganze Gemeinde Holzhauer und Wasserträger werden, wie ihnen die Fürsten vorgeschlagen hatten."',
        22: 'Und Josue berief sie und sprach zu ihnen: "Warum habt ihr uns betrogen mit den Worten: \'Wir wohnen sehr weit von euch\', und ihr wohnt doch in unserer Nähe?',
        23: 'Nun seid ihr verflucht. Nicht soll es bei euch an Sklaven, Holzhauern und Wasserträgem für meines Gottes Haus mangeln!"',
        24: 'Da antworteten sie Josue und sprachen: "Deinen Sklaven ist berichtet worden, was der Herr, dein Gott, seinem Diener Moses geboten, ihr sollet alle Insassen des Landes vor euch vertilgen, wenn er euch das ganze Land gebe. Da fürchteten wir von euch um unser Leben und taten so.',
        25: 'Nun sind wir in deiner Hand. Tu mit uns, wie es dir gut und recht dünkt!"',
        26: 'Da tat er mit ihnen so und schützte sie vor den Israeliten, und so haben sie sie nicht umgebracht.',
        27: 'Damals machte sie Josue zu Holzhauern und Wasserträgern für die Gemeinde und für den Altar des Herrn, für die Stätte, die er erwählen würde, bis zu diesem Tage.',
    },
    10: {
        1: 'Der König von Jerusalem nun, Adonisedek, hörte, daß Josue Ai erobert und es gebannt habe. Wie er Jericho und seinem König getan, so habe er auch Ai und seinem König getan, und Gibeons Einwohner hätten mit Israel Frieden geschlossen und gehörten zu ihnen.',
        2: 'Da fürchteten sie sich sehr. Denn Gibeon war eine große Stadt wie irgendeine Reichsstadt. Sie war größer als Ai, und alle ihre Männer waren tapfere Leute.',
        3: 'Da sandte Jerusalems König Adonisedek zu Hebrons König, Hoham, zu dem von Jarmut, Piram, zu dem von Lachis, Japhia, und zu Eglons König, Debir, und ließ sagen:',
        4: '"Zieht zu mir herauf und helft mir! Wir wollen Gibeon schlagen dafür, daß es mit Josue und den Israeliten Frieden geschlossen."',
        5: 'Da taten sich die fünf Amoriterkönige zusammen und zogen heran, der König von Jerusalem, der von Hebron, der von Jarmut, der von Lachis und der von Eglon, mit ihren ganzen Heeren. Und sie lagerten gegen Gibeon und bestürmten es.',
        6: 'Da sandten die Gibeoniter zu Josue ins Lager nach dem Gilgal und ließen sagen: "Zieh deine Hand nicht von deinen Sklaven! Komm schnell zu uns und hilf uns! Denn alle Amoriterkönige auf dem Gebirge scharen sich wider uns."',
        7: 'Da zog Josue mit dem ganzen Kriegsvolk, lauter tapferen Männern, vom Gilgal aus.',
        8: 'Und der Herr sprach zu Josue: "Hab keine Furcht vor ihnen! Ich gebe sie in deine Hand. Nicht einer von ihnen hält dir stand."',
        9: 'Und Josue überfiel sie plötzlich. Denn er war die ganze Nacht vom Gilgal heraufgezogen.',
        10: 'Und der Herr verwirrte sie vor Israel, und dieses schlug sie bei Gibeon schwer, verfolgte sie gegen die Steige von Bet Choron und schlug sie bis Azeka und Makeda.',
        11: 'Als sie, vor Israel fliehend, auf dem Abhang von Bet Choron waren, warf der Herr auf sie große Steine vom Himmel bis nach Azeka, daß sie starben. Und durch Hagelsteine starben mehr, als die Israeliten mit dem Schwert umgebracht hatten.',
        12: 'Damals sprach Josue zum Herrn an dem Tage, da der Herr die Amoriter den Israeliten preisgab. Er sprach in der Israeliten Gegenwart: "Sonne, steh still zu Gibeon; du Mond, im Tale Ajalon!"',
        13: 'Und still stand der Lauf des Mondes und der Sonne, bis über seine Feinde ein Volk den Sieg gewonnen. Steht es nicht so geschrieben im Buche des Richtigen? Die Sonne stand still mitten am Himmel und eilte nicht unterzugehen, den ganzen Tag.',
        14: 'Wie dieser Tag ist keiner zuvor noch nachher gewesen, daß der Herr der Stimme eines Menschen gefolgt hätte. Denn der Herr hatte für Israel gestritten.',
        15: 'Dann kehrte Josue mit ganz Israel ins Lager zurück nach dem Gilgal.',
        16: 'Jene fünf Könige aber flohen und versteckten sich in der Höhle bei Makeda.',
        17: 'Da ward Josue gemeldet: "Die fünf Könige hat man in der Höhle bei Makeda versteckt gefunden."',
        18: 'Da befahl Josue: "Wälzt große Steine vor den Eingang der Höhle und stellt Männer als Wache dabei auf!',
        19: 'Ihr anderen aber bleibt nicht stehen! Verfolgt eure Feinde! Vernichtet ihre Nachhut! Laßt sie nicht in ihre Städte kommen! Denn der Herr, euer Gott, gibt sie in eure Hand."',
        20: 'So schlugen Josue und die Israeliten sie sehr schwer bis zur Vernichtung. Einige von ihnen aber waren entkommen, und sie gelangten in die festen Städte.',
        21: 'Das ganze Volk kehrte nun zu Josue ins Lager nach Makeda unangefochten zurück. Niemand wagte es, gegen Israel auch nur leise etwas zu sagen.',
        22: 'Da befahl Josue: "Öffnet den Höhleneingang und bringt mir aus der Höhle jene fünf Könige!"',
        23: 'Sie taten so und brachten ihm jene fünf Könige aus der Höhle, den König von Jerusalem, den von Hebron, den von Jarmut, den von Lachis und den von Eglon.',
        24: 'Als man jene Könige zu Josue brachte, rief Josue alle Männer Israels herbei und sprach zu den Obersten der Kriegsleute, die mit ihm gezogen: "Kommt heran und setzt diesen Königen den Fuß auf den Nacken." Da kamen sie heran und setzten ihnen den Fuß auf den Nacken.',
        25: 'Und Josue sprach zu ihnen: "Seid ohne Furcht und unverzagt! Seid fest und mutig! So tut der Herr mit all euren Feinden, gegen die ihr streitet."',
        26: 'Hierauf schlug sie Josue und tötete sie. Dann hängte er sie an fünf Pfähle. Und sie hingen an den Pfählen bis zum Abend.',
        27: 'Gegen Sonnenuntergang befahl Josue, sie von den Pfählen zu nehmen. Man warf sie in die Höhle, in der sie sich versteckt hatten. Dann legte man große Steine vor der Höhle Eingang, bis zu diesem Tage.',
        28: 'Und Makeda eroberte Josue am gleichen Tage; er schlug es samt seinem König mit des Schwertes Schärfe. Er hatte sie gebannt und alle anderen Menschen darin. Er hatte keinen einzigen übriggelassen. Und mit Makedas König tat er so, wie er mit Jerichos König getan.',
        29: 'Und Josue zog mit ganz Israel von Makeda nach Libna und stritt wider Libna.',
        30: 'Der Herr gab auch dieses samt dem König in Israels Hand, und Israel schlug es mit des Schwertes Schärfe, sowie alle anderen Leute darin. Keinen einzigen hat es übriggelassen. Und mit seinem Könige tat es so, wie es mit Jerichos König getan.',
        31: 'Und Josue zog mit ganz Israel von Libna nach Lachis, lagerte davor und stritt dawider.',
        32: 'Und der Herr gab Lachis in Israels Hand. Es nahm es am zweiten Tage ein und schlug es mit des Schwertes Schärfe, sowie alle anderen Menschen darin, ganz so, wie es bei Libna getan.',
        33: 'Damals zog Gezers König, Horam, heran, Lachis zu helfen. Aber Josue schlug ihn und sein Volk so, daß von ihm niemand übrigblieb, der hätte entrinnen können.',
        34: 'Und Josue zog mit ganz Israel von Lachis nach Eglon. Sie lagerten davor und stritten dawider.',
        35: 'Sie nahmen es am selben Tag und schlugen es mit des Schwertes Schärfe, und alle Leute darin bannten sie an jenem Tage, ganz so, wie sie bei Lachis getan.',
        36: 'Und Josue zog mit ganz Israel von Eglon nach Hebron hinauf, und sie stritten dawider.',
        37: 'Sie nahmen es und schlugen es mit des Schwertes Schärfe, auch den König und alle seine Städte und alle Leute darin. Keinen einzigen haben sie entkommen lassen, ganz so, wie sie bei Eglon getan. Die Stadt und alle Leute darin bannten sie.',
        38: 'Dann wandte sich Josue mit ganz Israel gegen Debir und griff es an.',
        39: 'Er nahm es samt seinem König und alle seine Städte. Sie schlugen sie mit des Schwertes Schärfe und bannten alle Leute darin. Keinen einzigen hatte er entkommen lassen. Wie er mit Hebron getan und wie mit Libna und seinem König, so tat er mit Debir und seinem König.',
        40: 'So bezwang Josue das ganze Land, das Bergland, das Südland, die Niederung und das Hügelland mit all ihren Königen. Keinen hatte er entkommen lassen. Alles Lebende hatte er gebannt, wie der Herr, Israels Gott, befohlen hatte.',
        41: 'Und Josue bezwang sie von Kades Barnea bis Gaza und das ganze Land Gosen bis Gibeon.',
        42: 'Alle jene Könige und ihr Land nahm Josue auf einmal. Denn der Herr, Israels Gott, hatte für Israel gestritten.',
        43: 'Hierauf kehrten Josue und ganz Israel ins Lager nach dem Gilgal zurück.',
    },
    11: {
        1: 'Als aber Jabin, der König von Chasor, davon hörte, sandte er zu Madons König, Johab, zum König von Simron und zum König von Achsaph,',
        2: 'sowie zu den Königen im Norden, im Bergland, in der Steppe südlich von Kinerot, in der Niederung und auf dem Höhenzug von Dor am Meere,',
        3: 'zu den Kanaanitern im Osten und Westen, den Amoritern, Chittitern, Perizitern und Jebusitern auf dem Gebirge und zu den Chiwitern am Fuße des Hermon im Lande der Mispa.',
        4: 'Sie zogen mit all ihren Heeren aus, ein starkes Volk, zahlreich wie der Sand am Meeresstrande, und mit sehr viel Rossen und Wagen.',
        5: 'Und alle Könige kamen einhellig zusammen und lagerten insgesamt beim Wasser von Merom, wider Israel zu streiten.',
        6: 'Aber der Herr sprach zu Josue: "Furchte dich nicht vor ihnen! Morgen um diese Zeit lege ich sie alle erschlagen vor Israel hin. Ihre Rosse sollst du lähmen und ihre Streitwagen verbrennen! -',
        7: 'Da kam Josue mit dem ganzen Kriegsvolk unvermutet über sie beim Wasser von Merom, und sie überfielen sie.',
        8: 'Und der Herr gab sie in Israels Hand. Sie schlugen sie und verfolgten sie bis Groß-Sidon und bis Misrephot Maim sowie bis in die Talebene von Mispa im Osten. Und sie schlugen sie. Keinen einzigen von ihnen hat er entkommen lassen.',
        9: 'Josue tat an ihnen, wie ihm der Herr gesagt. Ihre Rosse lähmte er und verbrannte ihre Streitwagen.',
        10: 'Dann kehrte Josue um und eroberte Chasor. Seinen König aber hatte er mit dem Schwerte geschlagen. Chasor war vordem die Vormacht aller jener Königreiche gewesen.',
        11: 'Und sie schlugen darin alle Leute mit des Schwertes Schärfe und bannten sie. Kein Hauch war mehr übriggeblieben. Chasor selbst hatte er verbrannt.',
        12: 'All jene Königsstädte mit all ihren Königen nahm Josue und schlug sie mit des Schwertes Schärfe, hatte er sie doch gebannt, wie es des Herrn Diener, Moses, befohlen hatte.',
        13: 'Aber von all den Städten, die auf ihrem Hügel saßen, verbrannte Israel keine; allein Chasor hatte Josue verbrannt.',
        14: 'Die Israeliten aber nahmen die ganze Beute aus jenen Städten und das Vieh für sich. Nur die Menschen alle hatten sie mit des Schwertes Schärfe bis zur Vernichtung geschlagen. Keinen Hauch hatten sie übriggelassen.',
        15: 'Wie der Herr seinem Diener Moses befohlen, so hatte dieser dem Josue geboten, und so hatte Josue getan. Nichts unterließ er von allem, was der Herr dem Moses geboten.',
        16: 'So eroberte Josue dieses ganze Land, das Bergland, das ganze Südland, das ganze Land Gosen, die Niederung und die Steppe sowie das Bergland von Israel und seine Niederung,',
        17: 'vom kahlen Gebirge an, das gegen Seïr ansteigt, bis Baal Gad in der Libanonebene am Fuß des Hermon. Alle ihre Könige hatte er gefangen; dann schlug er sie und tötete sie.',
        18: 'Lange Zeit führte Josue mit all jenen Königen Krieg.',
        19: 'Keine Stadt ergab sich den Israeliten friedlich, außer die zu Gibeon wohnenden Chiwiter. Sonst hatten sie alles durch Kampf genommen.',
        20: 'Denn vom Herrn war es gefügt worden, ihr Herz zu verstocken zum Kampfe gegen Israel, daß man sie bannte, damit ihnen keine Schonung zuteil würde, sondern Ausrottung, wie der Herr dem Moses befohlen.',
        21: 'Damals kam Josue und vertilgte die Enakiter auf dem Gebirge, zu Hebron, Debir und Anab, auf dem ganzen Gebirge Juda und Israel. Sie und ihre Städte hatte Josue gebannt.',
        22: 'So blieben keine Enakiter mehr im Lande der Israeliten. Nur in Gaza, Gat und Asdod blieb ihrer ein Rest.',
        23: 'Josue nahm das ganze Land, wie es der Herr dem Moses geboten. Und Josue gab es Israel zu eigen nach ihrer Stammeseinteilung. Und das Land ruhte vom Kriege.',
    },
    12: {
        1: 'Dies sind des Landes Könige, die die Israeliten geschlagen und deren Land sie eingenommen haben: Jenseits des Jordan im Osten vom Arnonflusse bis zum Hermongebirge und die ganze Steppe im Osten.',
        2: 'Der Amoriterkönig Sichon, der zu Chesbon wohnte und der das Land beherrschte von Aroër am Ufer des Arnonflusses an und die Mitte des Tales sowie die eine Hälfte Gileads bis zum Jabbokfluß, die Grenze der Ammoniter,',
        3: 'sowie die Steppe bis zum See Genesareth im Osten und bis zum Meer der Steppe, dem Salzmeer, im Osten gegen Bet Hajesimot und südlich am Fuße der Zusammenflüsse des Pisga',
        4: 'und das Uferland. Ferner der König von Basan, Og, der zu den Rephaiterresten gehörte und zu Astarot und Edreï wohnte',
        5: 'und herrschte über das Hermongebirge, Salka und ganz Basan bis zur Grenze der Gesuriter und Maakatiter sowie über Gileads andere Hälfte bis zu dem Gebiete Sichons, des Königs von Chesbon.',
        6: 'Des Herrn Diener, Moses, und die Israeliten hatten sie besiegt, und Moses, des Herrn Diener, hatte es den Rubeniten, Gaditen und dem Halbstamm Manasse zu eigen gegeben.',
        7: 'Dies sind des Landes Könige, die Josue und die Israeliten jenseits des Jordan besiegt haben, westlich von Baal Gad im Libanontale bis zum glatten, gegen Seïr ansteigenden Gebirge, und das Josue den Stämmen Israels nach ihren Abteilungen zu eigen gab,',
        8: 'auf dem Gebirge, in der Niederung, in der Steppe, an den Zusammenflüssen, in der Wüste und im Südland, das Land der Chittiter, Amoriter, Kanaaniter, Periziter, Chiwiter und Jebusiter.',
        9: 'Ein König von Jericho, einer von Ai neben Betel,',
        10: 'einer von Jerusalem, einer von Hebron,',
        11: 'einer von Jarmut, einer von Lachis,',
        12: 'einer von Eglon, einer von Gezer,',
        13: 'einer von Debir, einer von Geder,',
        14: 'einer von Chorma, einer von Arad,',
        15: 'einer von Libna, einer von Adullam,',
        16: 'einer von Makeda, einer von Betel,',
        17: 'einer von Tappuach, einer von Chepher,',
        18: 'einer von Aphek, einer von Saron,',
        19: 'einer von Madon, einer von Chasor,',
        20: 'einer von Simron Meron, einer von Achsaph,',
        21: 'einer von Taanak, einer von Megiddo,',
        22: 'einer von Kedes, einer von Jokneam am Karmel,',
        23: 'einer von Dor bei Naphat Dor, einer von den Heiden im Gilgal,',
        24: 'einer von Tirsa; zusammen 31 Könige.',
    },
    13: {
        1: 'Als Josue alt und hochbetagt war, sprach der Herr zu ihm: "Du bist jetzt alt und hochbetagt. Noch aber bleibt ein großer Teil des Landes zu erobern.',
        2: 'Dies ist das Gebiet, das noch fehlt: alle Philisterbezirke und das ganze Gesur.',
        3: 'Von dem Sichor östlich von Ägypten bis zur Nordgrenze Ekrons, das zum Gebiet der Kanaaniter gerechnet wird: die fünf Fürsten der Philister, der von Gaza, der von Asdod, der von Askalon, der von Gat und der von Ekron, dazu die Awiter',
        4: 'im Süden, das ganze Kanaaniterland und die sidonische Höhle bis Aphek und bis an die Amoritergrenze',
        5: 'und das giblitische Land, sodann der ganze Libanon im Osten, von Baal Gad am Fuße des Hermongebirges bis ganz Chamat.',
        6: 'Alle Gebirgsbewohner vom Libanon bis Misrephot Maim, sämtliche Sidonier. Ich selbst vertreibe sie vor den Israeliten. Verlose es an Israel zum Erbbesitz, wie ich dir befohlen habe!',
        7: 'Verteile nun dies Land als Erbbesitz an die neun Stämme und an den Halbstamm Manasse!"',
        8: 'Mit ihm haben die Rubeniten und Gaditen ihren Erbbesitz erhalten, den ihnen Moses jenseits des Jordan angewiesen, wie ihn des Herrn Diener, Moses, ihnen angewiesen hat:',
        9: 'von Aroër am Ufer des Arnonflusses und von der Stadt mitten im Tale, dazu die ganze Ebene von Medeba bis Dibon',
        10: 'sowie alle Städte des Amoriterkönigs Sichon zu Chesbon bis zur Ammonitergrenze,',
        11: 'ferner Gilead und das Gebiet der Gesuriter und Maakatiter sowie das Hermongebirge und ganz Basan bis Salka,',
        12: 'das ganze Königreich Ogs zu Basan, der zu Astarot und Edreï herrschte. Dieser war von den Rephaiterresten noch da. Diese besiegte Moses und vertrieb sie.',
        13: 'Nicht vertrieben haben die Israeliten die Gesuriter und Maakatiter, und so blieben Gesur und Maakat unter Israel bis auf diesen Tag wohnen.',
        14: 'Nur dem Levitenstamm hat er kein Erbe gegeben, weil des Herrn, des Gottes Israels, Mähler sein Erbe sind, wie er ihm verheißen hat.',
        15: 'Und Moses gab den Sippen des Rubenitenstammes Land.',
        16: 'Sie bekamen das Gebiet von Aroër am Ufer des Arnonflusses und die Stadt mitten im Tal, dazu die ganze Ebene bei Medeba,',
        17: 'Chesbon und alle seine Städte in der Ebene, Dibon, Bamot Baal, Bet Baal Meoti,',
        18: 'Jahsa, Kedemot, Mephaat,',
        19: 'Kirjataim, Sibma, Seret Hasachar auf dem Berge der Talebene,',
        20: 'Bet Peor, die Zusammenflüsse des Pisga, Bet Hajesimot',
        21: 'und alle anderen Städte in der Ebene sowie das ganze Königreich des Amoriterkönigs Sichon, der zu Chesbon herrschte und das Moses besiegthat samt den Midianiterfürsten Ewi, Rekem, Sur, Chur und Reba, den im Lande ansässigen Vasallen Sidions.',
        22: 'Auch den Wahrsager Bileam, Beors Sohn, haben die Israeliten mit dem Schwert getötet wie die anderen, die sie erschlagen hatten.',
        23: 'Das Gebiet der Rubeniten ward der Jordan und das Uferland. Das ist der Erbbesitz der einzelnen Rubenitensippen, die Städte und ihre Dörfer.',
        24: 'Moses begabte auch den Stamm Gad, die einzelnen Sippen der Gaditen, und zwar erhielten sie folgendes Gebiet:',
        25: 'Jazer, alle Städte Gileads und die Hälfte des Ammoniterlandes bis Aroër östlich von Rabba,',
        26: 'und zwar von Chesbon bis Ramat Hamispe und Betonim sowie von Machanaim bis zum Gebiet von Debir,',
        27: 'ferner in der Talebene Bet Haram, Bet Nimra, Sukkot und Saphon, den Rest des Königreiches Sichons, des Königs von Chesbon, mit dem Jordan und dem Uferland bis zum Ende des Genesarethsees, jenseits, östlich des Jordan.',
        28: 'Das ist der Erbbesitz der einzelnen Gaditensippen, die Städte und ihre Dörfer.',
        29: 'Moses gab auch dem Halbstamm Manasse Land. Die einzelnen Sippen des Halbstammes Manasse erhielten folgendes Gebiet:',
        30: 'Ihr Gebiet umfaßte von Machanaim ganz Basan, das ganze Königreich des Basankönigs Og, und sämtliche Zeltdörfer Jairs in Basan, sechzig Städte,',
        31: 'dazu halb Gilead, sowie Astarot und Edreï, die Städte des Königreichs Og in Basan. Dies bekamen die Söhne Makirs, des Manassesohnes, und zwar die einzelnen Sippen der einen Hälfte der Makirsöhne.',
        32: 'Das ist es, was Moses in Moabs Steppen, jenseits, östlich des Jordan bei Jericho, zu eigen gegeben hat.',
        33: 'Dem Levitenstamm hat Moses kein Erbe gegeben; der Herr, Israels Gott, ist ihr Erbe, wie er ihnen verheißen hat.',
    },
    14: {
        1: 'Dies ist es, was die Israeliten im Lande Kanaan zu eigen bekommen und was ihnen der Priester EIeazar, Josue, Nuns Sohn, und die Stammeshäupter der israelitischen Stämme',
        2: 'durch das Los als ihren Erbbesitz verteilt haben, wie der Herr dem Moses für die neuneinhalb Stämme befohlen.',
        3: 'Denn den zweieinhalb Stämmen hatte Moses jenseits des Jordan ihren Erbbesitz gegeben, den Leviten aber keinen unter ihnen.',
        4: 'Denn die Josephsöhne waren zwei Stämme, Manasse und Ephraim. Aber den Leviten hat man im Lande kein Teil gegeben, außer Städte zum Wohnen und ihre Weidetriften für allerhand Herden.',
        5: 'Wie der Herr dem Moses befohlen, so haben die Israeliten getan und das Land verteilt.',
        6: 'Da traten die Judäer im Gilgal zu Josue, und der Keniziter Kaleb, Jephunnes Sohn, sprach zu ihm: "Du kennst das Wort, das der Herr zu Moses, dem Mann Gottes, meiner- und deinetwegen zu Kades Barnea gesprochen hat.',
        7: 'Ich war vierzig Jahre alt, als des Herrn Diener, Moses, mich von Kades Barnea aussandte, das Land zu erforschen. Ich brachte ihm Bescheid, wie es mir ums Herz war.',
        8: 'Meine Brüder aber, die mit mir hinaufgezogen, haben das Herz des Volkes verzagt gemacht. Ich aber bin hinter den Herrn, meinen Gott, getreten.',
        9: "An jenem Tage versprach Moses feierlich: 'Wahrlich, dir selbst und deinen Nachkommen sei das Land, das dein Fuß betritt, für immer Erbbesitz; denn du bist hinter den Herrn, meinen Gott, getreten.'",
        10: 'Nun hat mich der Herr, wie er gesagt, volle fünfundvierzig Jahre leben lassen seit der Zeit, da der Herr dies zu Moses gesagt und da Israel in der Wüste umhergezogen. So bin ich jetzt fünfundachtzig Jahre alt.',
        11: 'Noch immer bin ich so rüstig wie damals, als mich Moses ausgesandt hat. Meine Kraft von heute gleicht meiner Kraft von damals im Kampfe, bei Auszug und Heimkehr.',
        12: 'So gib mir jetzt dieses Bergland, von dem der Herr an jenem Tage gesprochen! Denn du hast selbst damals gehört, daß es dort Enakiter mit großen, festen Städten gibt. Vielleicht ist der Herr mit mir, daß ich sie vertreiben kann, wie der Herr versprochen hat."',
        13: 'Da segnete ihn Josue und gab Hebron dem Jephunnesohne Kaleb zum Erbe.',
        14: 'Deshalb hatte der Keniziter Kaleb, Jephunnes Sohn, Hebron zum Erbe bekommen bis auf diesen Tag, weil er hinter den Herrn, den Gott Israels, getreten war.',
        15: 'Hebron hieß vormals die Stadt des Arba; dieser war der bedeutendste Mann bei den Enakitern. Und das Land ruhte vom Kriege.',
    },
    15: {
        1: 'Die Sippen des Judastammes erhielten ihr Los nach der Grenze Edoms hin, südwärts nach der Wüste Sin zu, im äußersten Süden.',
        2: 'Ihre Südgrenze beginnt mit dem Ende des Salzmeeres, von der nach Süden gerichteten Zunge,',
        3: 'und geht südlich von der Skorpionensteige hinüber nach Sin und läuft südlich von Kades Barnea aufwärts nach Chesron hinüber. Dann geht sie aufwärts nach Adar und wendet sich nach Karka.',
        4: 'Dann geht sie nach Asmon hinüber und geht bis zum Bache Ägyptens, bis die Grenze am Meer endigt. Das sei eure Südgrenze!',
        5: 'Die Ostgrenze ist das Salzmeer bis zur Jordanmündung. Die Nordgrenze beginnt mit der Meereszunge und der Jordanmündung.',
        6: 'Dann läuft die Grenze aufwärts nach Bet Chogla und hinüber bis nördlich von Bet Haaraba. Dann läuft die Grenze aufwärts zum Steine Bohans, des Rubensohnes.',
        7: 'Dann zieht sich die Grenze aufwärts nach Debir vom Achortale her und wendet sich nördlich nach dem Gilgal, gegenüber der Steige von Adummim südlich vom Bache. Sodann läuft die Grenze hinüber nach dem Wasser der Sonnenquelle und weiter bis zur Rogelquelle.',
        8: 'Sodann läuft die Grenze aufwärts ins Tal Ben Hinnom südlich vom Bergrücken der Jebusiter, das ist Jerusalems. Dann läuft die Grenze aufwärts auf den Gipfel des Berges westlich vor dem Hinnomtal und am nördlichen Ende der Rephaimebene.',
        9: 'Vom Gipfel des Berges biegt die Grenze zur Quelle des Nephtoawassers um und geht zu den Städten des Ephrongebirges. Dann biegt die Grenze nach Baala, das ist Kirjat Jearim, um.',
        10: 'Voll Baala wendet sich die Grenze westwärts zum Berge Seïr, läuft hinüber nördlich vom Rücken des Waldberges, das ist Kesalon, zieht sich nach Bet Semes hinab und nach Timna hinüber.',
        11: 'Dann geht die Grenze nördlich weiter bis zum Bergrücken von Ekron. Dann biegt die Grenze nach Sikron um, geht hinüber nach dem Berg von Baala und läuft weiter bis Jabneel. So endet die Grenze am Meer.',
        12: 'Die Westgrenze ist das große Meer mit dem Küstenland. Das ist das Gebiet der Judäer ringsum nach ihren Sippen.',
        13: 'Dem Jephunnesohn Kaleb aber gab er unter den Judäern ein Teil nach dem Befehle des Herrn an Josue, nämlich die Stadt Arbas, des Enakvaters, das ist Hebron.',
        14: 'Und Kaleb vertrieb von da die drei Enaksöhne Sesai, Achiman und Talmai, die Sprößlinge Enaks.',
        15: 'Von dort zog er gegen Debirs Einwohner. Debir hieß früher Kirjat Sepher.',
        16: 'Und Kaleb versprach: "Wer Kirjat Sepher bezwingt und erobert, dem gebe ich meine Tochter Aksa zum Weibe."',
        17: 'Und Otniel, der Sohn des Kenaz, des Bruders Kalebs, eroberte es. Da gab er ihm seine Tochter Aksa zum Weibe.',
        18: 'Als sie hinzog, überlistete sie ihren Vater, da sie von ihm ein Feld wollte. Sie neigte sich nämlich vom Esel, so daß Kaleb sie fragte: "Was ist dir?"',
        19: 'Sie aber sprach: "Gib mir doch eine Abschiedsgabe! Du vergibst mich ja nach dem Südlande. So gib mir Wasser!" Da gab er ihr oberirdische und unterirdische Wasserstellen.',
        20: 'Das ist der Erbbesitz des Stammes der Judäer nach ihren Sippen:',
        21: 'Die Städte für den Judäerstamm, alles mitgerechnet, waren gegen Edoms Grenze hin im Südland: Kabseel, Eder, Jagur,',
        22: 'Kina, Dimona, Adada,',
        23: 'Kedes, Chasor und Jitnan,',
        24: 'Siph, Telem, Bealot,',
        25: 'Chasor Chadatta und Kerijot Chesron, das ist Chazor,',
        26: 'Amam, Sema, Molada,',
        27: 'Chasar Gadda, Chesmon, Bet Pelet,',
        28: 'Chasar Sual, Beer Seba und seine Tochterstädte,',
        29: 'Baala Ijim, Esem,',
        30: 'Eltolad, Kesil, Chorma,',
        31: 'Siklag, Madmanna, Sansanna,',
        32: 'Lebaot, Silchim, En-Rimmon, zusammen neunundzwanzig Städte mit ihren Dörfern.',
        33: 'In der Niederung: Estaol, Sora, Asna,',
        34: 'Zanoach, En Gannim, Tapuach und Enam,',
        35: 'Jarmut, Adullam, Soko, Azeka,',
        36: 'Saaraim, Aditaim, Gedera und seine Gehöfte; vierzehn Städte mit ihren Dörfern.',
        37: 'Senan, Chadasa, Migdal Gad,',
        38: 'Dilan, Hamispe, Jokteel,',
        39: 'Lakis, Boskat, Eglon,',
        40: 'Kabbon, Lachmas, Kitlis,',
        41: 'Gederot, Bet Dagon, Naama und Makeda, sechzehn Städte mit ihren Dörfern.',
        42: 'Libna, Eter, Aasan,',
        43: 'Jiphtach, Asna, Nesib,',
        44: 'Kegila, Akzib und Maresa, neun Städte mit ihren Dörfern.',
        45: 'Ekron mit seinen Ortschaften und Dörfern.',
        46: 'Von Ekron bis zum Meer alles, was neben Asdod und seinen Dörfern lag.',
        47: 'Asdod mit seinen Ortschaften und Dörfern, Gaza mit seinen Ortschaften und Dörfern bis zum Bache Ägyptens. Das große Meer bildete die Grenze.',
        48: 'Auf dem Gebirge: Sanir, Jattir, Soko,',
        49: 'Danna, Kirjat Sanna, das ist Debir,',
        50: 'Anab, Estemo, Anim,',
        51: 'Gosen, Cholon, Gilo, elf Städte und ihre Dörfer.',
        52: 'Arab, Duma, Esan,',
        53: 'Janum, Bet Tappuach, Aphekal,',
        54: 'Chumta, Kirjat Arba, das ist Hebron, und Sior, neun Städte und ihre Gehöfte.',
        55: 'Maon, Karmel, Ziph, Juta,',
        56: 'Jezreel, Jokneam und Zanoach,',
        57: 'Hakain, Gibea und Timma, zehn Städte mit ihren Dörfern,',
        58: 'Chalchul, Bet Sur und Gedor,',
        59: 'Maarat, Bet Anot und Eltekon, sechs Städte mit ihren Dörfern.',
        60: 'Kirjat Baal, das ist Kirjat Jearim, und Rabba, zwei Städte mit ihren Dörfern.',
        61: 'In der Steppe: Bet Haaraba, Middin, Sekaka,',
        62: 'Nibsan und die Salzstadt sowie Engeddi, sechs Städte mit ihren Dörfern.',
        63: 'Die Jebusiter, Jerusalems Bewohner, hatten die Judäer nicht vertreiben können. Und so blieben die Jebusiter mit den Judäern in Jerusalem bis auf diesen Tag beisammen.',
    },
    16: {
        1: 'Das Los der Söhne Josephs ging vom Jordan bei Jericho an Jerichos Gewässern im Osten, gegen die Steppe zu, die von Jericho zum Gebirge Betels hinaufzieht.',
        2: 'Dann lief die Grenze von Betel, dem alten Luz, nach dem Arkitergebiete nach Atarot hinüber,',
        3: 'senkte sich westlich nach dem Japhletitergebiet bis zum Gebiet des unteren Bet Choron und bis Gezer. Sie endigte am Meer.',
        4: 'Auch Josephs Söhne, Manasse und Ephraim, erhielten Erbbesitz.',
        5: 'Das Gebiet der Ephraimiten nach ihren Sippen war folgendes: Im Osten war ihres Erbbesitzes Grenze Aterot Adar bis zum oberen Bet Choron.',
        6: 'Dann lief die Grenze bis zum Meer, im Norden nach Mikmetat. Dann wandte sich die Grenze östlich nach Taanat Silo und zog östlich von Janoach vorüber.',
        7: 'Von Janoach lief sie nach Atarot und Naarat hinab, stieß an Jericho und endete am Jordan.',
        8: 'Von Tappuach lief die Grenze westwärts bis zum Kanabach und endete am Meer. Das ist der Erbbesitz des Ephraimitenstammes nach seinen Sippen.',
        9: 'Dazu die ephraimitischen Städte, die abgesondert inmitten des Erbbesitzes der Manassiten lagen, sämtliche Städte mit ihren Dörfern.',
        10: 'Sie hatten aber die Kanaaniter zu Gezer nicht vertrieben. So blieben die Kanaaniter inmitten Ephraims bis auf diesen Tag und wurden zu dienstbaren Sklaven.',
    },
    17: {
        1: 'Auch der Stamm Manasse bekam sein Los; denn er war Josephs Erstgeborener. Dem Erstgeborenen Manasses, Makir, dem Vater Gileads, fielen Gilead und Basan zu; denn er war ein Kriegsmann.',
        2: 'Auch die übrigen Nachkommen Manasses erhielten nach ihren Sippen ihr Teil: die Söhne Abiezers, Cheleks, Asriels, Sekems, Chephers und Semidas. Das sind die männlichen Nachkommen Manasses, des Josephsohns, nach ihren Sippen.',
        3: 'Selophchad, Chephers Sohn und Gileads Enkel, Urenkel des Sohnes Makirs, des Manassesohnes, hatte keine Söhne, sondern nur Töchter. Seine Töchter hießen Machla, Noa, Chogla, Milka und Tirsa.',
        4: 'Sie traten nun vor den Priester Eleazar und vor Josue, Nuns Sohn, und vor die Fürsten mit den Worten: "Der Herr hat Moses geheißen, uns unter unseren Brüdern einen Erbbesitz zu geben." Da gab er ihnen nach des Herrn Befehl einen Erbbesitz unter ihres Vaters Brüdern.',
        5: 'So fielen auf Manasse zehn Teile, abgesehen vom Lande Gilead und Basan, jenseits des Jordan,',
        6: 'weil Manasses Töchter unter seinen Söhnen Erbbesitz erhalten hatten. Das Land Gilead aber fiel den anderen Manassesöhnen zu.',
        7: 'Manasses Grenze ging von Asser nach Mikmetat östlich von Sichem. Dann lief die Grenze nach rechts zu den Insassen von En Tappuach.',
        8: 'Die Landschaft Tappuach gehörte Manasse, Tappuach aber an Manasses Grenze den Ephraimiten.',
        9: 'Dann lief die Grenze zum Kanabach hinab. Südlich vom Bache gehörte diese Stadt den Ephraimiten inmitten der Manassestädte. Sodann ging die Grenze Manasses nördlich vom Bach und endete am Meer.',
        10: 'Was südwärts lag, gehörte zu Ephraim, was nordwärts, zu Manasse, und das Meer war die Grenze. Im Norden grenzten sie an Asser, im Osten an Issakar.',
        11: 'In Issakar und Asser gehörten zu Manasse Bet Sean mit seinen Dörfern, Ibleam mit den seinigen, die Bewohner Dors mit seinen Dörfern, ebenso die von En Dor mit seinen Dörfern und die von Megiddo mit den seinigen, die drei Höhenzüge.',
        12: 'Die Manassiten konnten aber die genannten Städte nicht erobern. So bequemten sich die Kanaaniter dazu, in dieser Gegend zu bleiben.',
        13: 'Als aber die Israeliten erstarkten, machten sie die Kanaaniter fronpflichtig. Aber ganz vertrieben hatten sie sie nicht.',
        14: 'Da sprachen die Josephsöhne zu Josue: "Warum hast du mir nur ein Los und ein Teil zum Erbbesitz gegeben? Und doch habe ich viele Leute, weil mich darin der Herr gesegnet hat."',
        15: 'Josue sprach zu ihnen: "Hast du viele Leute, so steige ins Waldgebirge und rode dir dort etwas im Periziter- und Rephaiterlande! Das Gebirge Ephraim ist in eurer Nähe!"',
        16: 'Da sprachen die Josephsöhne: "Das Gebirge reicht für uns nicht. Alle Kanaaniter aber, die in der Ebene wohnen, haben eiserne Wagen, so die zu Betsean und die in seinen Dörfern und die in der Jezreelebene wohnen."',
        17: 'Da sprach Josue zum Josephshause, zu Ephraim und Manasse: "Du hast viel Leute und große Macht. So bleibt es für dich nicht bei einem Lose.',
        18: 'Ein Bergland wird dir aber von Wert sein, weil es Wald ist. Wenn du ihn rodest, fallen dir seine Einkünfte zu. Du mußt aber auch den Kanaaniter vertreiben, obschon er eiserne Wagen hat und stark ist."',
    },
    18: {
        1: 'Die ganze israelitische Gemeinde versammelte sich nun zu Silo. Und dort stellten sie das Festgezelt auf. Das Land aber lag unterworfen vor ihnen.',
        2: 'Unter den Israeliten waren aber noch sieben Stämme übrig, die noch keinen Erbbesitz erhalten hatten.',
        3: 'Da sprach Josue zu den Israeliten: "Wie lange zögert ihr noch, hinzugehen und das Land zu besetzen, das euch der Herr, eurer Väter Gott, gegeben?',
        4: 'Bringet drei Männer aus jedem Stamm, so sende ich sie aus, und sie sollen sich aufmachen, das Land durchziehen und es aufschreiben nach der Größe ihres Besitzes! Dann sollen sie zu mir kommen!',
        5: 'Hierauf sollen sie es in sieben Teile teilen! Juda behält sein Gebiet im Süden, das Josephshaus im Norden.',
        6: 'Ihr aber zeichnet das Land in sieben Teilen auf und berichtet mir hierher! Dann werfe ich hier vor dem Herrn, unserem Gott, das Los für euch.',
        7: 'Denn die Leviten haben kein Teil bei euch; vielmehr ist des Herrn Priestertum ihr Erbe. Gad aber und Ruben sowie der Halbstamm Manasse haben jenseits, östlich des Jordan ihren Erbbesitz erhalten, den ihnen des Herrn Diener, Moses, angewiesen hat."',
        8: 'Da machten sich die Männer auf und gingen. Die Ausziehenden hieß Josue das Land aufzeichnen, indem er sprach: "Geht hin! Durchzieht das Land! Zeichnet es auf! Dann kommt wieder zu mir! Ich werfe dann hier vor dem Herrn zu Silo für euch das Los!"',
        9: 'Da gingen die Männer, durchzogen das Land und zeichneten es Stadt für Stadt in sieben Teilen in ein Buch. Dann kamen sie zu Josue in das Lager nach Silo.',
        10: 'Da warf Josue zu Silo vor dem Herrn für sie das Los. So verteilte Josue dort den Israeliten das Land nach ihren Abteilungen.',
        11: 'Da kam das Los des Stammes der Benjaminsöhne für seine Sippen heraus. Das Gebiet ihres Loses lag zwischen den Judäern und den Josephsöhnen.',
        12: 'Ihre Grenze ging nördlich vom Jordan aus. Dann zog sich die Grenze aufwärts zu dem Bergrücken nördlich von Jericho und weiter hinauf auf das Gebirge nach Westen zu und lief nach der Steppe von Bet Awen aus.',
        13: 'Von da ging die Grenze nach Luz hinüber, auf die Südseite des Bergrückens von Luz, das ist Betel. Dann stieg die Grenze nach Aterot Addar hinab, dann auf den Berg südlich vom unteren Bet Choron.',
        14: 'Dann bog die Grenze um und wandte sich auf ihrer Westseite nach Süden, von dem Berg aus, der südlich von Bet Choron liegt, und endete bei Kirjat Baal, das ist die judäische Stadt Kirjat Jearim. Das ist die Westseite.',
        15: 'Die Südgrenze lief von der Stadtgrenze Kirjat Jearims aus. Dann ging die Grenze westwärts bis zur Quelle des Nephtoachwassers.',
        16: 'Dann lief die Grenze hinab bis ans Ende des Berges, östlich vom Ben-Hinnomstal und nördlich der Rephaimebene. Dann lief sie ins Hinnomstal hinab südlich vom Bergrücken der Jebusiter und weiter hinab zur Rogelquelle.',
        17: 'Dann bog sie nach Norden und lief auf die Quelle von Semes zu. Dann lief sie zu den Gelilot, gegenüber der Steige von Adummim, und zog sich zum Felsen des Rubensohnes Bohan hinab',
        18: 'und hinüber zu dem Bergrücken, nördlich der Steppe gegenüber. Dann lief sie in die Steppe hinab.',
        19: 'Dann ging die Grenze hinüber bis nördlich vom Bergrücken von Bet Chogla. Die Grenze endete an der Nordspitze des Salzmeeres, am Südende des Jordan. Das ist die Südgrenze.',
        20: 'Auf der Ostseite war der Jordan ihre Grenze. Das sind die Grenzen rings um den Erbbesitz der Benjaminitensippen.',
        21: 'Die Städte der Sippen des Benjaminitenstammes waren: Jericho, Bet Chogla, Kesistal,',
        22: 'Bet Haaraba, Semaraim, Betel,',
        23: 'Awim, Happara, Ophra,',
        24: 'Kephar Haammoni, Haophni und Geba, zwölf Städte mit ihren Dörfern.',
        25: 'Gibeon, Harama, Beerot,',
        26: 'Hammispe, Hakkephira, Hammosa,',
        27: 'Rekem, Irpeel, Tarala,',
        28: 'Sela, Haeleph und die Jebusiterstadt, das ist Jerusalem, Gibeat und Kirjat Arim,, vierzehn Städte mit ihren Dörfern. Das ist der Erbbesitz der Benjaminitensippen.',
    },
    19: {
        1: 'Das zweite Los kam für Simeon heraus, für die Sippen des Stammes der Simeoniten. Ihr Erbbesitz lag mitten im judäischen Erbbesitz.',
        2: 'Sie bekamen als Erbbesitz: Beerseba, Sema, Molada,',
        3: 'Chasar Sual, Bala, Esem,',
        4: 'Eltolad, Betul, Chorma,',
        5: 'Siklag, Bet Hammarkabot, Chasar Susa,',
        6: 'Bet Lebaot und Saruchen, dreizehn Städte mit ihren Dörfern,',
        7: 'Ain, Rimmon, Eter und Asan, vier Städte mit ihren Dörfern,',
        8: 'dazu all die Dörfer rings um diese Städte bis Baalat Ber, dem Rama des Südlandes. Das ist der Erbbesitz der Sippen des Stammes der Simeoniten.',
        9: 'Aus dem judäischen Anteil stammte der Erbbesitz der Simeoniten. Denn das Teil der Judäer war für diese zu groß. So bekamen die Simeoniten ihr Land mitten in deren Erbbesitz.',
        10: 'Das dritte Los kam für die Zabuloniten heraus für ihre Sippen. Ihres Erbbesitzes Bereich erstreckte sich bis Sarid.',
        11: 'Nach Westen ging ihre Grenze aufwärts nach Marela, berührte Dabbeset und stieß an den Bach östlich von Jokneam.',
        12: 'Nach Osten, nach Sonnenaufgang, wandte sie sich von Sarid nach dem Gebiet von Kislot Tabor, lief nach Haddaberat und stieg nach Japhia.',
        13: 'Von da ging sie nach Osten gegen Sonnenaufgang hinüber nach Gat Chepher, Et Kasin, lief nach Rimmon und bog nach Hannea um.',
        14: 'Dann wandte sich die Grenze herum auf der Nordseite von Chanaton und endete im Tal von Iphtach El.',
        15: 'Kattat, Naphalal, Simron, Idala und Bethlehem, zwölf Städte mit ihren Dörfern.',
        16: 'Das ist der Erbbesitz der Zabulonitensippen: diese Städte mit ihren Dörfern.',
        17: 'Für Issakar kam das vierte Los heraus, für die Issakaritensippen.',
        18: 'Ihr Gebiet erstreckte sich über Jezreel, Hakkesullot, Sunem,',
        19: 'Chapharaini, Sion, Anacharat,',
        20: 'Harrabbit, Kisjon, Ebes,',
        21: 'Reemer, En Gannim, En Chadda und Bet Passes.',
        22: 'Die Grenze berührte Tabor, Sachasima und Bet Semes. Ihre Grenze endete am Jordan; sechzehn Städte mit ihren Dörfern.',
        23: 'Das ist der Erbbesitz der Sippen des Issakaritenstammes, die Städte mit ihren Dörfern.',
        24: 'Das fünfte Los kam für die Sippen des Asseritenstammes heraus.',
        25: 'Ihr Gebiet erstreckte sich über Chelkat, Chali, Beten, Aksaph,',
        26: 'Allammelek, Amad und Misal. Es stieß an den Karmel am Meer und an den Sichor von Libna.',
        27: 'Dann wandte es sich gen Sonnenaufgang nach Bet Dagon, berührte Zabulon und das Tal Iphtach El im Norden, Bet Haemek und Negiel und ging nordwärts nach Kabul,',
        28: 'Ebron, Rechob, Chammon und Kana bis zum großen Sidon.',
        29: 'Dann wandte sich die Grenze zurück nach Harannt und bis zur festen Stadt Tyrus. Dann wandte sich die Grenze nach Chos und endete am Meer, Machaleb, Akzib,',
        30: 'Akko, Aphek und Rechebot, zweiundzwanzig Städte mit ihren Dörfern.',
        31: 'Das ist der Erbbesitz der Sippen des Asseritenstammes: diese Städte mit ihren Dörfern.',
        32: 'Für die Naphtaliten kam das sechste Los heraus, für die Naphtalitensippen.',
        33: 'Ihre Grenze lief von Cheleph, von der Eiche bei Saanannim, Adami, Hannekeb und Jabneel bis Lakkum und endete am Jordan.',
        34: 'Dann wandte sich die Grenze westwärts nach Aznot Tabor, lief von da nach Chukkok, stieß im Süden an Zabulon, nach Westen an Asser, nach Osten in Juda an den Jordan.',
        35: 'Feste Städte waren Hassidim, Ser, Chammat, Rakkat, Kinneret,',
        36: 'Adma, Harama, Chasor,',
        37: 'Kedes, Edreï, En Chasor,',
        38: 'Ireon, Migdal El, Chorem, Bet Anat und Bet Semes, neunzehn Städte mit ihren Dörfern.',
        39: 'Das ist der Erbbesitz der Sippen des Naphtalitenstammes: die Städte mit ihren Dörfern.',
        40: 'Für die Sippen des Danitenstammes kam das siebente Los heraus.',
        41: 'Der Bereich ihres Erbbesitzes erstreckte sich über Sora, Estaol, Ir Semes,',
        42: 'Saalabin, Ajjalon, Itla,',
        43: 'Elon, Timnat, Ekron,',
        44: 'Elteke, Gibbeton, Baalat,',
        45: 'Jehud, Bene Berak, Gat Rimmon,',
        46: 'Me Hajjarkon und Harakkon samt der Küste bei Joppe.',
        47: 'Das Gebiet der Daniten aber ging ihnen verloren. So zogen die Daniten hinauf und kämpften gegen Lesem, eroberten es und schlugen es mit des Schwertes Schärfe. Sie besetzten es, siedelten darin und nannten es Lesem Dan nach ihres Ahnherrn Dan Namen.',
        48: 'Das ist der Erbbesitz der Sippen des Danitenstammes: diese Städte mit ihren Dörfern.',
        49: 'So beendeten sie die Verteilung des Landes nach seiner Ausdehnung. Die Israeliten aber gaben in ihrer Mitte dem Sohne Nuns, Josue, einen Erbbesitz.',
        50: 'Nach des Herrn Geheiß hatten sie ihm die Stadt gegeben, die er erbeten hatte. Timnat Zerach auf dem Gebirge Ephraim. Er befestigte die Stadt und siedelte darin.',
        51: 'Dies sind die Erbteile, die der Priester Eleazar und Nuns Sohn, Josue, mit den Stammhäuptern der israelitischen Männer zu Silo verlost haben vor dem Herrn an des Festgezeltes Pforte. So beendigten sie des Landes Verteilung.',
    },
    20: {
        1: 'Und der Herr redete also mit Josue:',
        2: '"Sprich zu den Söhnen Israels: Bestimmt euch die Zufluchtsstädte, von denen ich durch Moses zu euch gesagt habe,',
        3: 'daß ein Totschläger, der unvorsätzlich, unversehens einen Menschen totschlug, dorthin fliehe! Sie seien euch Zuflucht vor dem Bluträcher!',
        4: 'Er (der Totschläger) fliehe in eine dieser Städte, trete an des Stadttores Eingang und berichte seine Sache den Ältesten der Stadt! Dann sollen sie ihn zu sich in die Stadt nehmen und ihm einen Platz anweisen, und er bleibe bei ihnen!',
        5: 'Verfolgt ihn der Bluträcher, so dürfen sie ihm den Totschläger nicht ausliefern, weil er seinen Nächsten unwissentlich getötet und ihn nicht von früher her gehaßt hat.',
        6: 'Er bleibe in dieser Stadt, bis er vor der Gemeinde zum Gerichte gestanden, bis zum Tode des jeweiligen Hohenpriesters! Dann soll der Totschläger heimkehren; er gehe in seine Stadt und sein Haus, in die Stadt, aus der er geflohen ist.\'"',
        7: 'Da bestimmten sie Kedes in Galiläa auf dem Gebirge Naphtali, auf dem Gebirge Ephraim Sichern und Kirjat Arba, das ist Hebron auf dem Gebirge Juda.',
        8: 'Jenseits des Jordan bei Jericho im Osten bestellten sie Beser in der Steppe, auf der Hochebene vom Stamme Ruben, Ramot in Gilead vom Stamme Gad und Golan in Basan vom Stamme Manasse.',
        9: 'Dies waren die Freistädte für alle Israeliten und die Fremdlinge unter ihnen, daß dorthin alle fliehen sollten, die einen Menschen unvorsätzlich töteten, damit sie nicht durch einen Bluträcher stürben, bevor sie vor der Gemeinde gestanden hätten.',
    },
    21: {
        1: 'Nun traten die Familienoberhäupter der Leviten zu dem Priester Eleazar und zu Josue, Nuns Sohn, sowie zu den Stammhäuptern der israelitischen Stämme',
        2: 'und sprachen zu ihnen in Silo im Lande Kanaan: "Der Herr hat durch Moses befohlen, uns Städte zu Siedlungen und ihre Weiden für unser Vieh zu geben."',
        3: 'Da gaben die Israeliten auf des Herrn Befehl von ihrem Erbbesitz den Leviten folgende Städte mit ihren Weiden:',
        4: 'Das Los fiel auf die Kehatitensippen, und so erhielten bei den Leviten die Söhne des Priesters Aaron vom Judastamme, vom Simeonitenstamme und vom Stamme Benjamin durch das Los dreizehn Städte.',
        5: 'Die anderen Kehatiten aber erhielten von den Sippen des Ephraimstammes, dem Stamme Dan und von dem Halbstamme Manasse durch das Los zehn Städte.',
        6: 'Die Gersoniten erhielten von den Sippen des Issakarstammes, vom Asserstamme, vom Stamme Naphtali und vom Halbstamme Manasse in Basan durch Los dreizehn Städte.',
        7: 'Die Sippen der Merariten erhielten vom Stamme Ruben, vom Stamme Gad und vom Zabulonstamme zwölf Städte.',
        8: 'Und die Israeliten übergaben den Leviten diese Städte samt ihren Weiden durch das Los, wie der Herr durch Moses befohlen hatte.',
        9: 'Vom Stamme der Judasöhne und der Simeoniten trat man diese Städte ab, die man jetzt mit Namen nennt.',
        10: 'Von den Sippen der Kehatiter unter Levis Söhnen bekamen die Aaronsöhne, weil auf sie zuerst das Los fiel,',
        11: 'die Stadt Arbas, des Vaters Enaks, das ist Hebron, auf dem Gebirge Juda samt ihren Weiden ringsum.',
        12: 'Die Markung der Stadt mit ihren Dörfern aber hatte man Kaleb, Jephunnes Sohn, zu seinem Erbbesitze gegeben.',
        13: 'Den Söhnen des Priesters Aaron hatte man Hebron gegeben, die Zufluchtsstadt der Totschläger, samt ihren Weiden, ebenso Libna,',
        14: 'Jattir, Estemona,',
        15: 'Cholon, Debir,',
        16: 'Ajin, Juta, Bet Semes je mit ihren Weiden, neun Städte von seiten jener beiden Stämme.',
        17: 'Und vom Stamme Benjamin Gibeon samt seinen Weiden, ebenso Geba,',
        18: 'Anatot und Almon, vier Städte.',
        19: 'Somit bekamen die Söhne des Priesters Aaron insgesamt dreizehn Städte mit ihren Weiden.',
        20: 'Den Sippen der übrigen levitischen Kehatsöhne wurden ihre Losstädte vom Stamm Ephraim abgetreten.',
        21: 'Man gab ihnen Sichem als Zufluchtsstadt der Totschläger, mit ihren Weiden auf dem Gebirge Ephraim, ebenso Gezer,',
        22: 'Kibsaim und Bet Choron je mit ihren Weiden, vier Städte.',
        23: 'Vom Stamme Dan Elteke, Gibbeton,',
        24: 'Ajjalon und Gat Rimmon je mit ihren Weiden, vier Städte.',
        25: 'Vom Halbstamme Manasse Taanak und Gat Rimmon mit je ihren Weiden, zwei Städte.',
        26: 'Somit bekamen die Sippen der übrigen Kehatsöhne insgesamt zehn Städte Mit ihren Weiden.',
        27: 'Die Gersoniten unter den Levitensippen bekamen vom Halbstamme Manasse Golan als Zufluchtsstadt der Totschläger, in Basan und Astarot, je mit ihren Weiden, zwei Städte.',
        28: 'Vom Issakarstamme Kisjon, Daberat,',
        29: 'Jarmut und En Gannim je mit ihren Weiden, vier Städte.',
        30: 'Vom Asserstamme Misal, Abdon',
        31: 'Chelkat und Rechob je mit ihren Weiden, vier Städte.',
        32: 'Vom Naphtalistamme Kedes als Zufluchtsstadt der Totschläger in Galiläa, Chammot Dor und Kartan je mit ihren Weiden, drei Städte.',
        33: 'Somit bekamen die Gersonitensippen insgesamt dreizehn Städte mit ihren Weiden.',
        34: 'Die übrigen levitischen Meraritensippen bekamen vom Zabulonstamme Jokneam, Karta,',
        35: 'Dimna und Nahalal mit ihren Weiden, vier Städte.',
        36: 'Vom Rubenstamme Beser, Jahsa,',
        37: 'Kedemot und Mephaat je mit ihren Weiden, vier Städte.',
        38: 'Vom Stamme Gad Ramot als Zufluchtsstadt der Totschläger in Gilead, Machanaim,',
        39: 'Chesbon und Jazer je mit ihren Weiden, insgesamt vier Städte.',
        40: 'So bekamen die von den Levitensippen übrigen Meraritensippen als ihr Los zwölf Städte.',
        41: 'Es waren also achtundvierzig Städte samt ihren Weiden inmitten des israelitischen Erbbesitzes Levitenstädte.',
        42: 'Diese Städte bestanden jedesmal aus einer Stadt und ihrer Weide ringsum. So war es bei all diesen Städten.',
        43: 'So gab der Herr Israel das ganze Land, das zu geben ihren Vätern er zugeschworen. Sie besetzten es und siedelten darin.',
        44: 'Und der Herr gab ihnen ringsum Ruhe, wie er ihren Vätern geschworen hatte. Von all ihren Feinden hatte keiner gegen sie standgehalten. Der Herr hatte all ihre Feinde in ihre Hand gegeben.',
        45: 'Von all den Verheißungen, die der Herr dem Haus Israel gegeben, war keine ausgeblieben. Alle waren in Erfüllung gegangen.',
    },
    22: {
        1: 'Damals berief Josue die Rubeniten, die Gaditen und den Halbstamm Manasse',
        2: 'und sprach zu ihnen: "Ihr habt alles befolgt, was euch des Herrn Diener, Moses, befohlen hat. Ihr gehorchtet meiner Stimme in allem, was ich euch geheißen.',
        3: 'Ihr habt eure Brüder diese lange Zeit hindurch nicht verlassen. Bis auf diesen Tag beobachtet ihr treulich die gebieterische Verpflichtung des Herrn, eures Gottes.',
        4: 'Nun hat der Herr, euer Gott, euren Brüdern Ruhe verliehen, wie er ihnen verheißen hat. Kehrt nun heim, dahin, wo euer Erbbesitz liegt, den euch des Herrn Diener, Moses, jenseits des Jordan gegeben!',
        5: 'Nur seid bemüht, das Gebot und die Weisung zu tun, die euch des Herrn Diener, Moses, gegeben. Ihr sollt den Herrn, euren Gott, lieben, immer auf seinen Wegen wandeln, seine Gebote befolgen, ihm anhangen und ihm von ganzem Herzen und aus ganzer Seele dienen!"',
        6: 'Und Josue segnete und entließ sie. So kehrten sie heim.',
        7: 'Der einen Hälfte des Manassestammes aber hatte Moses Besitz in Basan gegeben, der anderen Hälfte aber Josue bei ihren Brüdern westlich des Jordan. Auch sie hatte Josue mit Segenswünschen zu ihren Zelten entlassen.',
        8: 'Er sprach zu ihnen: "Kehrt mit viel Schätzen zu euren Zelten zurück, mit sehr viel Herden, mit Silber und Gold, Kupfer und Eisen und Gewändern in großer Menge! Teilet die Beute eurer Feinde mit euren Brüdern!"',
        9: 'So kehrten die Rubeniten heim, die Gaditen und der Halbstamm Manasse, und zogen von den Israeliten weg aus Silo im Lande Kanaan. Sie wollten in das Gileadland ziehen, in ihr Erbbesitzland, wo sie nach dem Befehl des Herrn an Moses angesiedelt waren.',
        10: 'So kamen sie am Jordan zu den Steinkreisen, die im Lande Kanaan waren. Da bauten dort die Rubeniten, Gaditen und der Halbstamm Manasse am Jordan einen weithin sichtbaren Altar.',
        11: 'Da hörten die Israeliten die Kunde, die Rubeniten, Gaditen und der Halbstamm Manasse hätten den Altar gebaut gegenüber dem Lande Kanaan an den Steinkreisen des Jordan jenseits der Söhne Israels.',
        12: 'Als die Israeliten dies hörten, versammelte sich die israelitische Gesamtgemeinde zu Silo, jene zu bekriegen.',
        13: 'Und die Israeliten sandten an die Rubeniten, Gaditen und den Halbstamm Manasse in das Land Gilead den Sohn des Priesters Eleazar, Pinechas,',
        14: 'nebst zehn Fürsten, je einen aus jedem Stamme Israels. Jeder war ein Oberhaupt israelitischer Stammesfamilien.',
        15: 'So kamen sie zu den Rubeniten, Gaditen und dem Halbstamm Manasse ins Land Gilead und sprachen zu ihnen:',
        16: '"So spricht die ganze Gemeinde des Herrn: \'Was bedeutet diese Untreue, die ihr am Gott Israels tut, euch heute vom Herrn abzuwenden, euch heute einen Altar zu bauen und so euch gegen den Herrn zu empören?',
        17: 'Ist uns der Peorfrevel zu gering? Davon haben wir uns bis heute noch nicht gereinigt, und deshalb kam über die Gemeinde des Herrn die Plage.',
        18: 'Und ihr wendet euch heute vom Herrn ab? So ist es: Heute empört ihr euch gegen den Herrn, und Morgen entlädt sich sein Zorn über die ganze Gemeinde Israels.',
        19: 'Ist aber euer Erbbesitzland unrein, dann zieht in das Erbbesitzland des Herrn hinüber, wo des Herrn Wohnung aufgeschlagen ist, und laßt euch bei uns nieder! Doch empört euch nicht gegen den Herrn! Aber auch uns verwickelt nicht in eure Empörung, wenn ihr außer dem Altar des Herrn, unseres Gottes, noch einen anderen bauet!',
        20: 'Ist nicht über die ganze Gemeinde ein Zorn gekommen, als sich Akan, Zerachs Sohn, am Banngut vergriffen hatte, und doch war er nur ein einzelner? Hat er nicht seiner Sünde wegen sterben müssen?\'"',
        21: 'Da sprachen die Rubeniten, Gaditen und der Halbstamm Manasse zu den Stammeshäuptern Israels:',
        22: '"Beim Gott der Götter, dem Herrn! Der Götter Gott, der Herr, weiß es, und Israel selbst wisse es! Geschah es in Untreue und Empörung, dann hilf uns heute nicht!',
        23: 'Bauten wir einen Altar, um vom Herrn abzufallen und um darauf Brand- und Speiseopfer zu opfern und um darauf Mahlopfer zu machen, dann soll es der Herr selbst ahnden!',
        24: "Ob wir dies nicht aus Sorge vor etwas getan? Wir dachten nämlich, eure Söhne könnten später zu unseren Söhnen sprechen: 'Was geht euch der Herr, Israels Gott, an?",
        25: "Hat doch der Herr den Jordan zur Grenze zwischen uns und euch gesetzt, ihr Rubeniten und Gaditen. Ihr habt am Herrn kein Teil.' So könnten eure Söhne die unsrigen so weit bringen, daß sie nicht mehr den Herrn fürchten.",
        26: "Darum sagten wir: 'Wir wollen uns durch den Bau des Altares vorsehen. Nicht für Brand- und Schlachtopfer,",
        27: 'sondern zum Zeugen sei er uns und euch und unseren Nachkommen, daß wir vor ihm den Dienst des Herrn tun wollen durch unsere Brand-, Schlacht- und Dankopfer, und daß künftig nicht eure Söhne zu den unsrigen sprechen: "Ihr habt kein Teil am Herrn."\'',
        28: 'Wir sagten: \'Sollten sie künftig so zu uns oder unseren Nachkommen sprechen, dann sagen wir: "Schaut die Bauart des Herrnaltares, den unsere Väter gebaut! Gemacht nicht für Brandopfer noch für Schlachtopfer, sondern nur zum Zeugen für uns und euch."',
        29: 'Ferne sei es uns, gegen den Herrn uns zu empören und heute vom Herrn abzufallen und für Brand-, Speise- und Schlachtopfer vor seiner Wohnung noch einen anderen Altar zu bauen, außer des Herrn, unseres Gottes, Altar.\'"',
        30: 'Als der Priester Pinechas und die Fürsten der Gemeinde, die Häupter der israelitischen Stämme bei ihm, die Worte hörten, die die Rubeniten, Gaditen und Manassiten redeten, gefiel es ihnen.',
        31: 'Und Pinechas, der Sohn des Priesters Eleazar, sprach zu den Rubeniten, Gaditen und Manassiten: "Heute erfahren wir, daß der Herr in unserer Mitte weilt, weil ihr keine Untreue gegen den Herrn getan. Damit habt ihr die Israeliten vor der Hand des Herrn bewahrt."',
        32: 'Dann kehrten Pinechas, der Sohn des Priesters Eleazar, und die Fürsten aus dem Lande Gilead von den Rubeniten und Gaditen ins Land Kanaan zu den Israeliten zurück und brachten ihnen Bescheid.',
        33: 'Und die Sache gefiel den Israeliten. Da priesen die Israeliten Gott und dachten nicht mehr daran, sie zu bekriegen und das Land, in dem die Rubeniten und Gaditen saßen, zu verwüsten.',
        34: 'Die Rubeniten und Gaditen aber rühmten von dem Altar: "Er ist unter uns Zeuge, daß der Herr Gott ist."',
    },
    23: {
        1: 'Geraume Zeit, nachdem der Herr Israel vor all seinen Feinden ringsum Ruhe verschafft und Josue alt und hochbetagt geworden,',
        2: 'berief Josue ganz Israel, seine Ältesten, Häupter, Richter und Amtleute und sprach zu ihnen: "Ich bin alt und hochbetagt.',
        3: 'Ihr habt alles selbst geschaut, was der Herr, euer Gott, all diesen Völkern euretwegen getan. Denn der Herr, euer Gott, hat selbst für euch gestritten.',
        4: 'Seht, ich überweise euch diese übriggebliebenen Heidenvölker durchs Los zum Eigentum für eure Stämme, vom Jordan an bis zum großen Meer im Westen, wie all die Heiden, die ich schon ausgerottet habe.',
        5: 'Der Herr, euer Gott, selbst verjagt sie vor euch und vertreibt sie vor euch, daß ihr ihr Land besetzet, wie euch der Herr, euer Gott, verheißen.',
        6: 'So tut euer Möglichstes, zu beachten und zu tun alles, was im Buch der Lehre Mosis geschrieben steht, ohne davon nach rechts oder links zu weichen!',
        7: 'Geratet nicht unter diese Heidenvölker, die bei euch übrig sind! Die Namen ihrer Götter sollt ihr nicht in den Mund nehmen und nicht bei ihnen schwören! Ihr sollt ihnen nicht dienen und euch nicht davor niederwerfen!',
        8: 'Dem Herrn, eurem Gott, sollt ihr anhangen, wie ihr es bis heute getan!',
        9: 'Deshalb vertrieb der Herr vor euch große und starke Heidenvölker, und niemand hielt bis heute vor euch stand.',
        10: 'Ein Mann von euch jagt tausend vor sich her. Denn der Herr, euer Gott, streitet selbst für euch nach seiner Verheißung.',
        11: "So gebt sorgfältig acht - gilt's doch euer Leben! -, daß ihr den Herrn, euren Gott, liebet!",
        12: 'Denn tut ihr anders und haltet ihr es mit dem Reste dieser Heidenvölker, die bei euch übrig sind, und verschwägert und vermischt ihr euch gegenseitig,',
        13: 'dann wisset, daß der Herr, euer Gott, diese Heidenvölker nicht mehr vor euch vertreiben wird! Sie werden euch dann zur Schlinge und zum Fallstrick, zu Geißeln in euren Seiten und zu Stacheln für eure Augen, bis ihr verdrängt seid aus diesem schönen Lande, das euch der Herr, euer Gott, gibt.',
        14: 'Ich gehe dieser Tage den Weg alles Irdischen. Dann seid von ganzem Herzen und aus ganzer Seele euch bewußt, daß von all den Verheißungen, die der Herr euch gegeben, keine seinerseits ausgeblieben ist! Alle sind für euch in Erfüllung gegangen. Keine davon ist ausgeblieben!',
        15: 'Aber wie sich alle Verheißungen erfüllt haben, die der Herr, euer Gott, euch gegeben, so wird der Herr auch alle Drohungen an euch erfüllen, bis er euch aus diesem schönen Land verdrängt hat, das euch der Herr, euer Gott, gegeben.',
        16: 'Übertretet ihr den Bund, den der Herr, euer Gott, euch geboten, und geht ihr hin, falschen Göttern zu dienen und euch vor ihnen hinzuwerfen, so wird des Herrn Zorn gegen euch entbrennen, und ihr werdet rasch aus dem schönen Land verdrängt, das er euch gegeben hat."',
    },
    24: {
        1: 'Josue versammelte nun alle Stämme Israels nach Sichem. Er berief dazu die Ältesten Israels sowie ihre Oberhäupter, Richter und Amtleute, und sie stellten sich vor Gott auf.',
        2: 'Da sprach Josue zum ganzen Volke: "So spricht der Herr, Israels Gott: \'In grauer Vorzeit haben eure Ahnen in dem Lande jenseits des Stromes gewohnt, der Vater Abrahams und Nachors, Terach, und sie dienten anderen Göttern.',
        3: 'Da wählte ich mir euren Ahnherrn Abraham aus dem Gebiete jenseits des Stromes und führte ihn im ganzen Lande Kanaan umher, vermehrte seinen Stamm und gab ihm Isaak.',
        4: 'Und Isaak schenkte ich Jakob und Esau, und Esau gab ich das Gebirge von Seïr zu eigen. Doch Jakob zog mit seinen Söhnen nach Ägypten.',
        5: 'Da sandte ich Moses und Aaron. Und ich schlug Ägypten durch das, was ich darin getan. Dann habe ich euch weggeführt.',
        6: 'Ich führte eure Väter aus Ägypten. Und so kamet ihr an das Meer. Die Ägypter aber verfolgten eure Väter mit Wagen und mit Reitern bis an das Schilfmeer.',
        7: 'Da riefen sie zum Herrn. Er aber setzte zwischen euch und die Ägypter tiefe Finsternis und brachte über sie das Meer, daß es sie bedeckte. Und eure Augen sahen, was ich Ägypten getan. Dann weiltet ihr in der Wüste lange Zeit.',
        8: 'Hierauf brachte ich euch in das Land der Amoriter, jenseits des Jordan, und diese kämpften gegen euch. Ich aber gab sie in eure Hand. So nahmt ihr ihr Land weg, und ich tilgte sie vor euch.',
        9: 'Dann trat Balak auf, des Sippors Sohn und Moabs König, und stritt mit Israel. Er sandte hin und ließ Bileam, des Beor Sohn, rufen, euch zu verfluchen.',
        10: 'Ich aber wollte nicht auf Bileam hören. So gab er euch den Segen, und ich befreite euch aus seiner Hand.',
        11: 'Dann überschrittet ihr den Jordan und kamt nach Jericho. Da kämpften mit euch die Bürger Jerichos, die Amoriter, Periziter, Kanaaniter, Chittiter und Girgasiter, Chiwiter und Jebusiter. Und ich gab sie in eure Hand.',
        12: 'Ich sandte vor euch die Hornissen her. Sie vertrieben sie vor euch, zwei Könige der Amoriter, nicht durch dein Schwert und nicht durch deinen Bogen.',
        13: 'Ich gab euch ein Land, um das du dich nicht bemüht, und Städte, die ihr nicht gebaut, und ihr siedeltet darin. Weinberge und Olivengärten, die ihr nicht gepflanzt, genießet ihr.',
        14: 'So fürchtet den Herrn und dient ihm aufrichtig und treu! Schafft die Götter ab, denen eure Vorfahren jenseits des Stromes und in Ägypten gedient! Dient dem Herrn!',
        15: 'Mißfällt es euch aber, dem Herrn zu dienen, so wählt für euch heute, wem ihr dienen wollt, ob den Göttern, denen eure Ahnen jenseits des Stromes gedient, oder den Göttern der Amoriter, in deren Land ihr wohnt! Ich und mein Haus wollen dem Herrn dienen.\'"',
        16: 'Da antwortete das Volk und sprach: "Ferne sei es uns, den Herrn zu verlassen und anderen Göttern zu dienen!',
        17: 'Denn der Herr ist unser Gott. Er hat uns und unsere Väter aus Ägypten, wo wir Sklaven waren, hergeführt und vor unseren Augen diese großen Wunder getan und uns überall behütet auf dem Weg, den wir gegangen, und unter all den Völkern, durch die wir mitten durchgezogen.',
        18: 'So vertrieb der Herr vor uns alle Völker, auch die Amoriter, des Landes Insassen. Auch wir wollen dem Herrn dienen. Denn er ist unser Gott."',
        19: 'Josue sprach zum Volke: "Ihr könnt dem Herrn nicht dienen. Denn er ist ein heiliger Gott. Er ist ein eifersüchtiger Gott. Er vergibt euch nicht euren Frevel und eure Sünden.',
        20: 'Verlasset ihr den Herrn und dienet ihr ausländischen Göttern, so wird er anders werden. Er tut euch dann Übles und reibt euch auf, nachdem er euch wohlgetan."',
        21: 'Und das Volk sprach zu Josue: "Nein! Wir wollen doch dem Herrn dienen."',
        22: 'Da sprach Josue zum Volk: "Ihr seid Zeugen wider euch selbst, daß ihr euch für den Dienst des Herrn entschieden habt." Sie sprachen: "Jawohl!"',
        23: '"So schafft nun die ausländischen Götter bei euch weg und neigt euer Herz dem Herrn, dem Gott Israels, zu!"',
        24: 'Und das Volk sprach zu Josue: "Dem Herrn, unserem Gott, wollen wir dienen und auf seine Stimme hören."',
        25: 'Da schloß Josue an jenem Tage einen Bund mit dem Volke und gab ihm zu Sichem Satzung und Recht.',
        26: 'Und Josue schrieb dies in das Buch der Lehre Gottes. Dann nahm er einen großen Stein und stellte ihn dort unter die Eiche im Heiligtum des Herrn.',
        27: 'Josue aber sprach zum ganzen Volke: "Wohlan, dieser Stein sei Zeuge wider uns! Denn er hat all die Worte angehört, die der Herr mit uns gesprochen hat. Darum sei er Zeuge gegen euch, daß ihr euren Gott nicht verleugnet!"',
        28: 'Dann entließ Josue das Volk, jeden in sein Besitztum.',
        29: 'Hernach starb Josue, Nuns Sohn, des Herrn Diener, hundertzehn Jahre alt.',
        30: 'Sie begruben ihn im Bereiche seines Erbes zu Timnat Serach auf dem Gebirge Ephraim, nördlich vom Berg Gaas.',
        31: 'Und Israel diente dem Herrn alle Tage Josues und der Ältesten, die noch lange nach Josue lebten und die noch jedes Werk kannten, das der Herr für Israel getan hatte.',
        32: 'Josephs Gebeine aber, die die Israeliten aus Ägypten heraufgebracht hatten, hatten sie zu Sichem begraben, auf dem Feldstück, das Jakob von den Söhnen Chamors, des Vaters Sichems, um hundert Beutel gekauft hatte und das die Söhne Josephs als Erbe besaßen.',
        33: 'Auch Aarons Sohn Eleazar starb. Und sie begruben ihn auf seines Sohnes Pinechas Hügel, der ihm auf dem Gebirge Ephraim verliehen worden war.',
    },
}
